window.HP_DATA=[{"id": "sleep", "label": "8 hrs sleep", "title": "8 hours of sleep", "tier": "daily", "group": null, "blurb": "Eight hours a night, same bedtime and wake time every day, including weekends.", "sources": [{"title": "Sleep duration and all-cause mortality: a systematic review and meta-analysis of prospective studies", "authors": "Cappuccio FP, D'Elia L, Strazzullo P, et al.", "year": 2010, "journal": "Sleep", "doi": "10.1093/sleep/33.5.585", "pmid": "20469800", "pmcid": "PMC2864873", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2864873/", "type": "meta-analysis", "summary": "Pooled 16 prospective studies (27 cohorts, about 1.38 million adults, 112,566 deaths) relating self-reported sleep duration to all-cause mortality. Short sleep (usually under 6-7 hours) carried a 12% higher risk of death (RR 1.12) and long sleep (usually over 8-9 hours) a 30% higher risk (RR 1.30). Sleep was self-reported and long sleep may partly mark existing illness, so the takeaway is a U-shaped curve with the sweet spot around 7-8 hours, not that more is always better.", "highlight": "short duration of sleep was associated with a greater risk of death (RR: 1.12; 95% CI 1.06 to 1.18; P < 0.01)"}, {"title": "Sleep regularity is a stronger predictor of mortality risk than sleep duration: A prospective cohort study", "authors": "Windred DP, Burns AC, Lane JM, et al.", "year": 2024, "journal": "Sleep", "doi": "10.1093/sleep/zsad253", "pmid": "37738616", "pmcid": "PMC10782501", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10782501/", "type": "cohort", "summary": "Prospective UK Biobank cohort of 60,977 adults whose sleep timing was measured by wrist accelerometer for a week and who were followed for about 6.3 years. People in the more regular sleep-timing quintiles had a 20-48% lower risk of all-cause death than the least regular quintile, and regularity predicted mortality better than duration did. It is observational and based on one week of data in older UK adults, but it suggests keeping consistent bed and wake times matters as much as the hours.", "highlight": "Higher sleep regularity was associated with a 20%-48% lower risk of all-cause mortality"}, {"title": "Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society", "authors": "Watson NF, Badr MS, Belenky G, et al.", "year": 2015, "journal": "Sleep", "doi": "10.5665/sleep.4716", "pmid": "26039963", "pmcid": "PMC4434546", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4434546/", "type": "guideline", "summary": "A 15-member AASM and Sleep Research Society expert panel used a modified RAND Appropriateness Method to review the evidence and vote on how much sleep adults need. The panel concluded that adults should sleep 7 or more hours per night on a regular basis, and that habitually sleeping under 7 hours is linked to weight gain, diabetes, hypertension, heart disease, depression, impaired immunity and more errors. It is expert consensus rather than new data, and it notes that more than 9 hours may help young adults or people recovering from sleep debt or illness but is otherwise uncertain.", "highlight": "developed a consensus recommendation for the amount of sleep needed to promote optimal health in adults"}]}, {"id": "sunlight", "label": "Morning sunlight", "title": "Morning sunlight", "tier": "daily", "group": null, "blurb": "10–20 minutes outside within an hour of waking, no sunglasses (never look at the sun). Longer on cloudy days.", "sources": [{"title": "Time spent in outdoor light is associated with mood, sleep, and circadian rhythm-related outcomes: A cross-sectional and longitudinal study in over 400,000 UK Biobank participants", "authors": "Burns AC, Saxena R, Vetter C, et al.", "year": 2021, "journal": "Journal of affective disorders", "doi": "10.1016/j.jad.2021.08.056", "pmid": "34488088", "pmcid": "PMC8892387", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8892387/", "type": "cohort", "summary": "Cross-sectional and longitudinal analysis of about 400,000 UK Biobank adults who reported how much daylight time they spent outdoors. Each extra hour outdoors per day was tied to lower odds of depression and antidepressant use, fewer insomnia symptoms, less tiredness, and easier waking (OR about 1.46-1.49 for ease of getting up). Outdoor time was self-reported and light intensity at the eye was not measured, so this shows association, not proof that morning light specifically causes the benefit.", "highlight": "low daytime light exposure is an important environmental risk factor for mood, sleep, and circadian-related outcomes"}, {"title": "Brighter nights and darker days predict higher mortality risk: A prospective analysis of personal light exposure in >88,000 individuals", "authors": "Windred DP, Burns AC, Lane JM, et al.", "year": 2024, "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.2405924121", "pmid": "39405349", "pmcid": "PMC11513964", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11513964/", "type": "cohort", "summary": "Prospective UK Biobank study of 88,905 adults who wore a wrist light sensor for one week, followed for about 8 years (3,750 deaths). Those with the brightest daytime light had up to 17-34% lower all-cause mortality (aHR 0.66-0.83 for the top decile), while bright light at night raised risk by up to 21-34%. It is observational with one week of measurement, but it supports the practical rule: bright days, dark nights.", "highlight": "Minimizing night light, maximizing day light, and keeping regular light-dark patterns that enhance circadian rhythms may promote cardiometabolic health and longevity"}, {"title": "Effects of light on human circadian rhythms, sleep and mood", "authors": "Blume C, Garbazza C, Spitschan M", "year": 2019, "journal": "Somnologie : Schlafforschung und Schlafmedizin = Somnology : sleep research and sleep medicine", "doi": "10.1007/s11818-019-00215-x", "pmid": "31534436", "pmcid": "PMC6751071", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6751071/", "type": "review", "summary": "Narrative review of how light reaches the brain's master clock (the suprachiasmatic nucleus) via the retina and how light timing shapes circadian rhythms, sleep and mood. Light is the main signal that sets the body clock; morning light advances it, evening and night light delays it and suppresses melatonin, and bright light therapy is an effective low-risk treatment for some sleep and mood problems. This is a mechanism review rather than an outcome trial, so it explains why morning light should help more than it quantifies how much.", "highlight": "light can also be used as an effective and noninvasive therapeutic option with little to no side effects, to improve sleep,mood and general well-being"}]}, {"id": "floss", "label": "Floss & brush", "title": "Floss & brush", "tier": "daily", "group": null, "blurb": "Brush twice a day for two minutes, floss once.", "sources": [{"title": "Home use of interdental cleaning devices, in addition to toothbrushing, for preventing and controlling periodontal diseases and dental caries", "authors": "Worthington HV, MacDonald L, Poklepovic Pericic T, et al.", "year": 2019, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD012018.pub2", "pmid": "30968949", "pmcid": "PMC6953268", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6953268/", "type": "systematic review", "summary": "Cochrane review of 35 randomized trials (3,929 adults) comparing toothbrushing plus floss, interdental brushes, sticks or water irrigators against toothbrushing alone. Flossing on top of brushing modestly reduced gingivitis at 1, 3 and 6 months (SMD -0.58 at one month), and interdental brushes looked somewhat better than floss. The evidence was low to very low certainty and short term, with no trials measuring cavities between teeth, so the benefit is real but smaller and less proven than often claimed.", "highlight": "Using floss or interdental brushes in addition to toothbrushing may reduce gingivitis or plaque, or both, more than toothbrushing alone"}, {"title": "Improved oral hygiene care attenuates the cardiovascular risk of oral health disease: a population-based study from Korea", "authors": "Park SY, Kim SH, Kang SH, et al.", "year": 2019, "journal": "European heart journal", "doi": "10.1093/eurheartj/ehy836", "pmid": "30561631", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/30561631/", "type": "cohort", "summary": "Korean national cohort of 247,696 healthy adults aged 40+ who had an oral health screening and were followed for a median 9.5 years (14,893 major cardiovascular events). Each additional daily toothbrushing was associated with a 9% lower risk of cardiovascular events, and yearly professional cleaning with a 14% lower risk. It is observational and brushing habits travel with other healthy behaviors, so it supports but does not prove that oral hygiene protects the heart.", "highlight": "Performing one more tooth brushing a day was associated with a 9% significantly lower risk of cardiovascular events after multivariable adjustment"}, {"title": "Periodontal health, cognitive decline, and dementia: A systematic review and meta-analysis of longitudinal studies", "authors": "Asher S, Stephen R, Mäntylä P, et al.", "year": 2022, "journal": "Journal of the American Geriatrics Society", "doi": "10.1111/jgs.17978", "pmid": "36073186", "pmcid": "PMC9826143", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9826143/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 47 longitudinal studies on periodontal health (gum disease, tooth loss, bone loss) and later cognitive decline or dementia. Poor periodontal health was linked to 23% higher odds of cognitive decline (OR 1.23) and 21% higher risk of dementia (HR 1.21). The authors rate the evidence as low quality and note reverse causation is likely part of it (declining people stop caring for their teeth), so this is a plausible but unproven link.", "highlight": "Poor periodontal health and tooth loss appear to increase the risk of both cognitive decline and dementia"}]}, {"id": "water", "label": "Water (1 gal)", "title": "Water, 1 gallon", "tier": "daily", "group": null, "blurb": "About a gallon (3.8 L) through the day. That is above the usual guidance of about 2.7–3.7 L of total water from all food and drink, so spread it out and add electrolytes on sweaty days.", "sources": [{"title": "Middle-age high normal serum sodium as a risk factor for accelerated biological aging, chronic diseases, and premature mortality", "authors": "Dmitrieva NI, Gagarin A, Liu D, et al.", "year": 2023, "journal": "EBioMedicine", "doi": "10.1016/j.ebiom.2022.104404", "pmid": "36599719", "pmcid": "PMC9873684", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9873684/", "type": "cohort", "summary": "NIH analysis of 15,752 adults from the ARIC cohort enrolled at ages 45-66 and followed for 25 years, using serum sodium as a marker of habitual hydration. Mid-life serum sodium above 142 mmol/L was linked to 39% higher risk of chronic disease (HR 1.39), up to 50% higher odds of being biologically older than chronological age, and above 144 mmol/L to 21% higher premature mortality. Serum sodium is an indirect proxy and no one was told to drink more, so this supports staying well hydrated, not a specific target like a gallon a day.", "highlight": "have increased risk to be biologically older, develop chronic diseases and die at younger age"}, {"title": "Treatment effect, adherence, and safety of high fluid intake for the prevention of incident and recurrent kidney stones: a systematic review and meta-analysis", "authors": "Cheungpasitporn W, Rossetti S, Friend K, et al.", "year": 2016, "journal": "Journal of nephrology", "doi": "10.1007/s40620-015-0210-4", "pmid": "26022722", "pmcid": "PMC4831051", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4831051/", "type": "meta-analysis", "summary": "Meta-analysis of 9 studies (2 RCTs with 269 patients, 7 observational studies with about 274,000 people) comparing high versus low fluid intake for kidney stone prevention. High fluid intake cut the risk of kidney stones by roughly half to 60% (RR 0.40 in RCTs, 0.49 in observational studies), including recurrent stones. This is the best-established hard benefit of drinking more water, and it matters most for people prone to stones; safety data were thin.", "highlight": "This analysis demonstrated a significantly reduced risk of incident kidney stones among individuals with high fluid consumption"}, {"title": "Water, hydration, and health", "authors": "Popkin BM, D'Anci KE, Rosenberg IH", "year": 2010, "journal": "Nutrition reviews", "doi": "10.1111/j.1753-4887.2010.00304.x", "pmid": "20646222", "pmcid": "PMC2908954", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2908954/", "type": "review", "summary": "Narrative review in Nutrition Reviews of water intake, hydration physiology, and effects on energy intake, weight, kidney function, physical and cognitive performance. It reports that mild dehydration impairs mood and performance and that replacing sugary drinks with water reduces calorie intake, while noting that US guidance (the NASEM Adequate Intake of about 3.7 L/day for men and 2.7 L/day for women) counts total water including roughly 20% from food. There are no long-term randomized trials of higher water intake, and 1 gallon (about 3.8 L) of plain water per day exceeds typical guidance for most people unless they are large, very active or in heat; very high intake can rarely cause hyponatremia.", "highlight": "there are also few longer-term systematic interventions and no published randomized, controlled longer-term trials"}]}, {"id": "steps", "label": "10K steps", "title": "10,000 steps a day", "tier": "daily", "group": null, "blurb": "Walk. Every day. The single cheapest longevity habit with a clear dose-response curve.", "sources": [{"title": "Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts", "authors": "Paluch AE, Bajpai S, Bassett DR, et al.", "year": 2022, "journal": "Lancet Public Health", "doi": "10.1016/S2468-2667(21)00302-9", "pmid": "35247352", "pmcid": "PMC9289978", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9289978/", "type": "meta-analysis", "summary": "Participant-level meta-analysis of 15 cohorts covering 47,471 adults followed for a median of 7.1 years with device-measured steps. Compared with the lowest quartile (about 3,500 steps/day), the highest quartile (about 10,900 steps/day) had a 53% lower risk of death (HR 0.47). Benefits levelled off around 6,000-8,000 steps/day in adults 60 and older and 8,000-10,000 in younger adults, so 10,000 is not a magic threshold.", "highlight": "Taking more steps per day was associated with a progressively lower risk of all-cause mortality, up to a level that varied by age."}, {"title": "The association between daily step count and all-cause and cardiovascular mortality: a meta-analysis", "authors": "Banach M, Lewek J, Surma S, et al.", "year": 2023, "journal": "Eur J Prev Cardiol", "doi": "10.1093/eurjpc/zwad229", "pmid": "37555441", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/37555441/", "type": "meta-analysis", "summary": "Meta-analysis of 17 cohort studies with 226,889 participants followed for a median of 7.1 years. Each extra 1,000 steps/day was associated with a 15% lower risk of all-cause death, and each extra 500 steps/day with a 7% lower risk of cardiovascular death. The data are observational, so sicker people walking less (reverse causation) may inflate the benefit, but no upper limit of benefit was found.", "highlight": "A 1000-step increment was associated with a 15% decreased risk of all-cause mortality"}, {"title": "Daily steps and health outcomes in adults: a systematic review and dose-response meta-analysis", "authors": "Ding D, Nguyen B, Nau T, et al.", "year": 2025, "journal": "Lancet Public Health", "doi": "10.1016/S2468-2667(25)00164-1", "pmid": "40713949", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/40713949/", "type": "meta-analysis", "summary": "Systematic review of 57 prospective studies (31 in meta-analyses) linking device-measured steps to mortality, heart disease, cancer, diabetes, dementia, depression and falls. Compared with 2,000 steps/day, 7,000 steps/day was associated with 47% lower all-cause mortality, 25% lower cardiovascular disease incidence and 38% lower dementia risk. Most gains came by 5,000-7,000 steps/day, and several outcomes rested on only two to four studies.", "highlight": "7000 steps per day is associated with clinically meaningful improvements in health outcomes and might be a more realistic and achievable target for some"}]}, {"id": "sauna", "label": "Sauna", "title": "Sauna", "tier": "daily", "group": null, "blurb": "Regular heat exposure, roughly 20 minutes at 80°C+, ideally 4–7 sessions a week.", "sources": [{"title": "Association between sauna bathing and fatal cardiovascular and all-cause mortality events", "authors": "Laukkanen T, Khan H, Zaccardi F, Laukkanen JA", "year": 2015, "journal": "JAMA Intern Med", "doi": "10.1001/jamainternmed.2014.8187", "pmid": "25705824", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25705824/", "type": "cohort", "summary": "Prospective cohort of 2,315 middle-aged Finnish men (Kuopio study) followed for a median of 20.7 years. Men using the sauna 4-7 times a week had a 63% lower risk of sudden cardiac death (HR 0.37) than once-a-week users, with similar trends for heart disease and all-cause death. It is one observational cohort of men only, and frequent sauna use may partly mark better health, wealth and leisure time.", "highlight": "Increased frequency of sauna bathing is associated with a reduced risk of SCD, CHD, CVD, and all-cause mortality."}, {"title": "Sauna bathing is inversely associated with dementia and Alzheimer's disease in middle-aged Finnish men", "authors": "Laukkanen T, Kunutsor S, Kauhanen J, Laukkanen JA", "year": 2017, "journal": "Age Ageing", "doi": "10.1093/ageing/afw212", "pmid": "27932366", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/27932366/", "type": "cohort", "summary": "Same Kuopio cohort of 2,315 men aged 42-60, followed about 20 years for dementia and Alzheimer's diagnoses. Compared with once a week, sauna use 4-7 times a week was associated with a 66% lower dementia risk (HR 0.34) and 65% lower Alzheimer's risk. Case numbers in the top group were small and the cohort is all male and Finnish, so this is a hypothesis, not proof.", "highlight": "moderate to high frequency of sauna bathing was associated with lowered risks of dementia and Alzheimer's disease"}, {"title": "Cardiovascular and Other Health Benefits of Sauna Bathing: A Review of the Evidence", "authors": "Laukkanen JA, Laukkanen T, Kunutsor SK", "year": 2018, "journal": "Mayo Clin Proc", "doi": "10.1016/j.mayocp.2018.04.008", "pmid": "30077204", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/30077204/", "type": "review", "summary": "Narrative review of observational, experimental and interventional studies on Finnish sauna bathing and health. It reports links to lower blood pressure, cardiovascular disease, dementia and mortality, with plausible mechanisms such as better endothelial function and reduced arterial stiffness. It is written largely by the same group that produced the main cohort data, and randomized evidence on hard outcomes is lacking.", "highlight": "regular sauna bathing may improve cardiovascular function via improved endothelium-dependent dilatation, reduced arterial stiffness, modulation of the autonomic nervous system"}]}, {"id": "wimhof", "label": "Wim Hof breathing", "title": "Wim Hof breathing", "tier": "daily", "group": null, "blurb": "Rounds of deep cyclic breathing followed by breath holds. Sit or lie down, never in water or while driving.", "sources": [{"title": "Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans", "authors": "Kox M, van Eijk LT, Zwaag J, et al.", "year": 2014, "journal": "Proc Natl Acad Sci U S A", "doi": "10.1073/pnas.1322174111", "pmid": "24799686", "pmcid": "PMC4034215", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4034215/", "type": "RCT", "summary": "Small randomized trial in which 12 healthy men trained 10 days in Wim Hof-style breathing, meditation and cold exposure, versus 12 untrained controls, before an injection of bacterial endotoxin. The trained group had sharply higher adrenaline, higher anti-inflammatory IL-10, lower inflammatory cytokines and fewer flu-like symptoms. With 24 young men, a lab endotoxin model and no long-term outcomes, it shows a physiological effect, not a health benefit in daily life.", "highlight": "voluntary activation of the sympathetic nervous system results in epinephrine release and subsequent suppression of the innate immune response in humans in vivo"}, {"title": "Effect of breathwork on stress and mental health: A meta-analysis of randomised-controlled trials", "authors": "Fincham GW, Strauss C, Montero-Marin J, Cavanagh K", "year": 2023, "journal": "Sci Rep", "doi": "10.1038/s41598-022-27247-y", "pmid": "36624160", "pmcid": "PMC9828383", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9828383/", "type": "meta-analysis", "summary": "Meta-analysis of 12 RCTs (785 adults) on breathwork of many styles versus non-breathwork controls, with secondary analyses on anxiety and depression. Breathwork produced a small-to-medium reduction in self-reported stress (g = -0.35), with similar effects on anxiety and depressive symptoms. Most trials had moderate risk of bias and few tested Wim Hof breathing specifically, and the authors warn against hype outrunning evidence.", "highlight": "we urge caution and advocate for nuanced research approaches with low risk-of-bias study designs to avoid a miscalibration between hype and evidence"}, {"title": "Does the Wim Hof Method have a beneficial impact on physiological and psychological outcomes in healthy and non-healthy participants? A systematic review", "authors": "Almahayni O, Hammond L", "year": 2024, "journal": "PLoS One", "doi": "10.1371/journal.pone.0286933", "pmid": "38478473", "pmcid": "PMC10936795", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10936795/", "type": "systematic review", "summary": "Systematic review of studies on the Wim Hof Method or its breathing component, finding only nine papers from eight trials. The most consistent signal was an anti-inflammatory effect via raised adrenaline; effects on exercise performance and breathing parameters were mixed. The evidence base is tiny and heterogeneous, so claims beyond short-term inflammation changes are not well supported.", "highlight": "the findings of this review show promising use of WHM in the inflammatory response category"}]}, {"id": "dailydozen", "label": "Daily Dozen foods", "title": "Dr. Greger's Daily Dozen foods", "tier": "daily", "group": null, "blurb": "Greger's checklist: beans, berries, other fruit, cruciferous veg, greens, other veg, flaxseed, nuts & seeds, herbs & spices, whole grains, water, exercise. Evidence below is for its main food groups.", "sources": [{"title": "Fruit and vegetable intake and the risk of cardiovascular disease, total cancer and all-cause mortality-a systematic review and dose-response meta-analysis of prospective studies", "authors": "Aune D, Giovannucci E, Boffetta P, et al.", "year": 2017, "journal": "Int J Epidemiol", "doi": "10.1093/ije/dyw319", "pmid": "28338764", "pmcid": "PMC5837313", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5837313/", "type": "meta-analysis", "summary": "Dose-response meta-analysis of 95 prospective studies on fruit and vegetable intake and heart disease, cancer and death. Each 200 g/day was associated with 10% lower all-cause mortality, with risk falling up to about 800 g/day (roughly 10 servings). The studies are observational and produce eaters tend to have healthier lifestyles, though the dose-response pattern is consistent.", "highlight": "Fruit and vegetable intakes were associated with reduced risk of cardiovascular disease, cancer and all-cause mortality."}, {"title": "Whole grain consumption and risk of cardiovascular disease, cancer, and all cause and cause specific mortality: systematic review and dose-response meta-analysis of prospective studies", "authors": "Aune D, Keum N, Giovannucci E, et al.", "year": 2016, "journal": "BMJ", "doi": "10.1136/bmj.i2716", "pmid": "27301975", "pmcid": "PMC4908315", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4908315/", "type": "meta-analysis", "summary": "Dose-response meta-analysis of 45 prospective studies on whole grain intake. Each 90 g/day (about three servings) was associated with 19% lower coronary heart disease risk and 17% lower all-cause mortality. Refined grains and white rice showed little association, and residual confounding by overall healthy diet cannot be ruled out.", "highlight": "whole grain intake is associated with a reduced risk of coronary heart disease, cardiovascular disease, and total cancer, and mortality from all causes"}, {"title": "Nut consumption and risk of cardiovascular disease, total cancer, all-cause and cause-specific mortality: a systematic review and dose-response meta-analysis of prospective studies", "authors": "Aune D, Keum N, Giovannucci E, et al.", "year": 2016, "journal": "BMC Med", "doi": "10.1186/s12916-016-0730-3", "pmid": "27916000", "pmcid": "PMC5137221", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5137221/", "type": "meta-analysis", "summary": "Dose-response meta-analysis of 20 prospective studies on nut intake and disease and death. A daily handful (28 g) was associated with 29% lower coronary heart disease risk and 22% lower all-cause mortality. These are observational associations for one component of the Daily Dozen; no trial has tested Greger's full checklist on hard outcomes.", "highlight": "Higher nut intake is associated with reduced risk of cardiovascular disease, total cancer and all-cause mortality"}]}, {"id": "acv", "label": "Apple cider vinegar", "title": "Apple cider vinegar", "tier": "daily", "group": null, "blurb": "About 1 tablespoon diluted in water with a meal. Rinse after; it is hard on tooth enamel.", "sources": [{"title": "The effect of apple cider vinegar on lipid profiles and glycemic parameters: a systematic review and meta-analysis of randomized clinical trials", "authors": "Hadi A, Pourmasoumi M, Najafgholizadeh A, et al.", "year": 2021, "journal": "BMC Complement Med Ther", "doi": "10.1186/s12906-021-03351-w", "pmid": "34187442", "pmcid": "PMC8243436", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8243436/", "type": "meta-analysis", "summary": "Meta-analysis of nine clinical trials (10 arms) testing apple cider vinegar for at least two weeks. It lowered total cholesterol by about 6 mg/dL, fasting glucose by about 8 mg/dL and HbA1c by 0.5 points, with no effect on LDL, HDL, insulin or insulin resistance. Trials were small and highly heterogeneous, and effects mostly appeared in people with type 2 diabetes.", "highlight": "We found a significant favorable effect of ACV consumption on FPG and blood lipid levels."}, {"title": "Effects of apple cider vinegar on glycemic control and insulin sensitivity in patients with type 2 diabetes: A GRADE-assessed systematic review and dose-response meta-analysis of controlled clinical trials", "authors": "Arjmandfard D, Behzadi M, Sohrabi Z, et al.", "year": 2025, "journal": "Front Nutr", "doi": "10.3389/fnut.2025.1528383", "pmid": "39949546", "pmcid": "PMC11821484", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11821484/", "type": "meta-analysis", "summary": "Dose-response meta-analysis of seven controlled trials of apple cider vinegar in people with type 2 diabetes. Vinegar lowered fasting blood sugar by about 22 mg/dL and HbA1c by about 1.5 points, with no change in insulin resistance. Only seven small trials were pooled, and the effects apply to diabetics, not healthy people.", "highlight": "ACV had positive effects on FBS and HbA1c in T2DM patients."}, {"title": "Vinegar Consumption and Health: An Umbrella Review of Meta-Analyses of Randomized Controlled Trials", "authors": "Shahmohammadi F, Khosroshahi RA, Derakhshanian H, et al.", "year": 2026, "journal": "Food Sci Nutr", "doi": "10.1002/fsn3.71849", "pmid": "42110393", "pmcid": "PMC13149749", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13149749/", "type": "systematic review", "summary": "Umbrella review re-analysing 10 meta-analyses covering 38 trials of vinegar on cardiometabolic markers. Vinegar modestly improved fasting glucose (-9.4 mg/dL), HbA1c (-0.7%), body weight (-1.06 kg) and systolic blood pressure (-2.9 mmHg), with no effect on LDL, HDL, triglycerides, BMI or waist size. The effects are small, and a widely publicized 2024 BMJ Nutrition trial of apple cider vinegar for weight loss was retracted in 2025, so big weight-loss claims are unsupported.", "highlight": "Vinegar intake was associated with statistically significant improvements in FBG (moderate certainty), PPG (moderate certainty), HbA1c (moderate certainty)"}]}, {"id": "protein", "label": "Complete protein", "title": "Complete protein", "tier": "daily", "group": null, "blurb": "Get enough complete protein, meaning all nine essential amino acids: eggs, fish, meat, dairy, soy, quinoa, or plant proteins combined (beans + rice). Around 1.6 g per kg of body weight a day is where muscle gains level off in the research.", "sources": [{"title": "A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults", "authors": "Morton RW, Murphy KT, McKellar SR, et al.", "year": 2018, "journal": "British Journal of Sports Medicine", "doi": "10.1136/bjsports-2017-097608", "pmid": "28698222", "pmcid": "PMC5867436", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5867436/", "type": "meta-analysis", "summary": "This meta-analysis pooled 49 randomized trials (1,863 participants) of protein supplementation during at least 6 weeks of resistance training. Protein added about 2.49 kg to one-rep-max strength and 0.30 kg of fat-free mass, with no further gains beyond a total intake of about 1.62 g/kg/day. The effects are modest, shrink with age, and depend on actually doing resistance training.", "highlight": "Dietary protein supplementation significantly enhanced changes in muscle strength and size during prolonged RET in healthy adults."}, {"title": "Systematic review and meta-analysis of protein intake to support muscle mass and function in healthy adults", "authors": "Nunes EA, Colenso-Semple L, McKellar SR, et al.", "year": 2022, "journal": "Journal of Cachexia, Sarcopenia and Muscle", "doi": "10.1002/jcsm.12922", "pmid": "35187864", "pmcid": "PMC8978023", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8978023/", "type": "meta-analysis", "summary": "This meta-analysis of 74 randomized trials in healthy non-obese adults tested whether eating more daily protein increases lean mass, strength and physical function. More protein produced small gains in lean mass during resistance training (SMD 0.22), significant in adults 65+ at 1.2-1.59 g/kg/day and in younger adults at 1.6 g/kg/day or more. Effects on strength were slight and on physical function minimal, so protein is a helper to training, not a substitute.", "highlight": "increasing daily protein ingestion results in small additional gains in LBM and lower body muscle strength gains in healthy adults enrolled in resistance exercise training"}, {"title": "Dose-response relationship between protein intake and muscle mass increase: a systematic review and meta-analysis of randomized controlled trials", "authors": "Tagawa R, Watanabe D, Ito K, et al.", "year": 2020, "journal": "Nutrition Reviews", "doi": "10.1093/nutrit/nuaa104", "pmid": "33300582", "pmcid": "PMC7727026", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7727026/", "type": "meta-analysis", "summary": "This dose-response meta-analysis included 105 articles (5,402 participants) from randomized trials of protein intake and lean body mass. Each extra 0.1 g/kg/day of protein was linked to 0.39 kg more lean mass below a total intake of 1.3 g/kg/day, but only 0.12 kg above it. The practical takeaway is diminishing returns: raising protein matters most for people starting from low intake.", "highlight": "These findings suggest that slightly increasing current protein intake for several months"}]}, {"id": "stretching", "label": "20 min stretching", "title": "20 minutes of stretching", "tier": "daily", "group": null, "blurb": "Twenty minutes a day of static or dynamic stretching, hitting hips, hamstrings, chest and shoulders.", "sources": [{"title": "Chronic effects of stretching on range of motion with consideration of potential moderating variables: A systematic review with meta-analysis", "authors": "Konrad A, Alizadeh S, Daneshjoo A, Anvar SH, et al.", "year": 2024, "journal": "Journal of Sport and Health Science", "doi": "10.1016/j.jshs.2023.06.002", "pmid": "37301370", "pmcid": "PMC10980866", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10980866/", "type": "meta-analysis", "summary": "This meta-analysis pooled 77 studies (186 effect sizes) on regular stretch training in healthy people. Stretching reliably increased range of motion with a moderate effect (effect size about 1.0), with static and PNF stretching beating dynamic stretching. Volume, intensity and frequency did not clearly change the gains, so 20 minutes a day is likely more than needed for flexibility alone.", "highlight": "stretch training can increase ROM with a moderate effect compared to the controls"}, {"title": "Stretching is Superior to Brisk Walking for Reducing Blood Pressure in People With High-Normal Blood Pressure or Stage I Hypertension", "authors": "Ko J, Deprez D, Shaw K, Alcorn J, et al.", "year": 2021, "journal": "Journal of Physical Activity & Health", "doi": "10.1123/jpah.2020-0365", "pmid": "33338988", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/33338988/", "type": "RCT", "summary": "Forty adults (mean age 62) with high-normal blood pressure or stage 1 hypertension were randomized to 30 minutes of stretching or brisk walking, five days a week for eight weeks. Stretching lowered sitting systolic pressure from 146 to 140 mmHg and reduced other measures more than walking did. It is a single small trial, and walking's lack of effect is unusual, so treat this as promising rather than settled.", "highlight": "An 8-week stretching program was superior to brisk walking for reducing blood pressure in individuals with high-normal blood pressure or stage 1 hypertension."}, {"title": "The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials", "authors": "Lauersen JB, Bertelsen DM, Andersen LB", "year": 2014, "journal": "British Journal of Sports Medicine", "doi": "10.1136/bjsports-2013-092538", "pmid": "24100287", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/24100287/", "type": "meta-analysis", "summary": "This meta-analysis pooled 25 randomized trials with 26,610 participants and 3,464 injuries, comparing stretching, strength, balance and combined programs for injury prevention. Stretching showed no protective effect (RR 0.96, confidence interval crossing 1), while strength training cut injuries to under a third (RR 0.32). Stretch for range of motion and how it feels, but do not count on it to prevent injuries; strength work does that better.", "highlight": "consistently favourable estimates were obtained for all injury prevention measures except for stretching"}]}, {"id": "creatine", "label": "Creatine", "title": "Creatine monohydrate", "tier": "supplements", "group": null, "blurb": "Blueprint: 2.5 g in the Longevity Mix plus 5 g on its own.", "sources": [{"title": "Effect of creatine supplementation during resistance training on lean tissue mass and muscular strength in older adults: a meta-analysis", "authors": "Chilibeck PD, Kaviani M, Candow DG, et al.", "year": 2017, "journal": "Open Access Journal of Sports Medicine", "doi": "10.2147/OAJSM.S123529", "pmid": "29138605", "pmcid": "PMC5679696", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5679696/", "type": "meta-analysis", "summary": "This meta-analysis pooled 22 randomized trials (721 adults, mean age 57-70) comparing creatine with placebo during 7-52 weeks of resistance training. Creatine added about 1.4 kg more lean mass (95% CI 0.97-1.76 kg) and modestly larger gains in chest press and leg press strength. The benefit depends on lifting at the same time, and the strength effects are small to moderate.", "highlight": "creatine supplementation increases lean tissue mass and upper and lower body muscular strength during resistance training of older adults"}, {"title": "Effects of creatine supplementation on cognitive function of healthy individuals: A systematic review of randomized controlled trials", "authors": "Avgerinos KI, Spyrou N, Bougioukas KI, et al.", "year": 2018, "journal": "Experimental Gerontology", "doi": "10.1016/j.exger.2018.04.013", "pmid": "29704637", "pmcid": "PMC6093191", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6093191/", "type": "systematic review", "summary": "This systematic review looked at 6 randomized trials (281 healthy people) testing oral creatine on cognitive tests. Short-term memory and reasoning may improve, while results for attention, executive function, and reaction time were conflicting and young people showed no change. The evidence base is small, so the cognitive case is promising but unproven, with the best signal in older, stressed, or vegetarian people.", "highlight": "Oral creatine administration may improve short-term memory and intelligence/reasoning of healthy individuals but its effect on other cognitive domains remains unclear"}, {"title": "International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine", "authors": "Kreider RB, Kalman DS, Antonio J, et al.", "year": 2017, "journal": "Journal of the International Society of Sports Nutrition", "doi": "10.1186/s12970-017-0173-z", "pmid": "28615996", "pmcid": "PMC5469049", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5469049/", "type": "guideline", "summary": "This position stand from the International Society of Sports Nutrition reviews the research on creatine for performance, recovery, aging, and clinical uses. It concludes creatine reliably improves high-intensity exercise performance and training adaptations, and that doses up to 30 g/day for 5 years have been safe in healthy people. It is a consensus review by an industry-adjacent society rather than a fresh meta-analysis, but the core guidance of about 3-5 g/day is well supported.", "highlight": "short and long-term supplementation (up to 30 g/day for 5 years) is safe and well-tolerated in healthy individuals"}]}, {"id": "collagen", "label": "Collagen", "title": "Collagen peptides", "tier": "supplements", "group": null, "blurb": "Blueprint: collagen peptides at breakfast and mid-morning.", "sources": [{"title": "Effects of Oral Collagen for Skin Anti-Aging: A Systematic Review and Meta-Analysis", "authors": "Pu SY, Huang YL, Pu CM, et al.", "year": 2023, "journal": "Nutrients", "doi": "10.3390/nu15092080", "pmid": "37432180", "pmcid": "PMC10180699", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10180699/", "type": "meta-analysis", "summary": "This meta-analysis pooled 26 randomized trials (1,721 participants) of hydrolyzed collagen versus placebo for skin. Collagen significantly improved skin hydration and elasticity (both p < 0.00001), with hydration effects varying by collagen source and duration. The authors flag bias in many included trials, several of which are industry-funded, so the effect is real-looking but likely overstated.", "highlight": "the findings suggest that HC supplementation can have positive effects on skin health, but further large-scale randomized control trials are necessary"}, {"title": "The effects of collagen peptide supplementation on body composition, collagen synthesis, and recovery from joint injury and exercise: a systematic review", "authors": "Khatri M, Naughton RJ, Clifford T, et al.", "year": 2021, "journal": "Amino Acids", "doi": "10.1007/s00726-021-03072-x", "pmid": "34491424", "pmcid": "PMC8521576", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8521576/", "type": "systematic review", "summary": "This systematic review covered 15 randomized trials of collagen peptides combined with exercise, mostly in recreational athletes. The clearest benefit was improved joint function and less joint pain, with 15 g/day raising collagen synthesis but not muscle protein synthesis compared with higher-quality protein. Collagen is not a substitute for regular protein for muscle, and the trials were small.", "highlight": "The results indicated that COL is most beneficial in improving joint functionality and reducing joint pain"}, {"title": "Effect of collagen supplementation on knee osteoarthritis: an updated systematic review and meta-analysis of randomised controlled trials", "authors": "Simental-Mendía M, Ortega-Mata D, Acosta-Olivo CA, et al.", "year": 2025, "journal": "Clinical and Experimental Rheumatology", "doi": "10.55563/clinexprheumatol/kflfr5", "pmid": "39212129", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/39212129/", "type": "meta-analysis", "summary": "This meta-analysis pooled 11 randomized trials (870 people with knee osteoarthritis) of oral collagen-based supplements versus placebo. Collagen improved pain scores (mean difference -13.6) and function scores (mean difference -6.5). Heterogeneity was very high (I2 75-88%) and the collagen products varied, so the size of the benefit is uncertain.", "highlight": "The results of this meta-analysis suggest that oral collagen administration relieves OA symptoms"}]}, {"id": "omega3", "label": "Omega-3", "title": "Omega-3 (EPA/DHA)", "tier": "supplements", "group": null, "blurb": "Blueprint: EPA/DHA softgels.", "sources": [{"title": "Marine Omega-3 Supplementation and Cardiovascular Disease: An Updated Meta-Analysis of 13 Randomized Controlled Trials Involving 127 477 Participants", "authors": "Hu Y, Hu FB, Manson JE", "year": 2019, "journal": "Journal of the American Heart Association", "doi": "10.1161/JAHA.119.013543", "pmid": "31567003", "pmcid": "PMC6806028", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6806028/", "type": "meta-analysis", "summary": "This meta-analysis pooled 13 randomized trials (127,477 participants, mean 5 years) of marine omega-3 supplements. Even excluding REDUCE-IT, omega-3 lowered heart attack risk by about 8% (RR 0.92) and cardiovascular death by about 7% (RR 0.93), with larger doses linked to larger reductions. The relative reductions are small, so the absolute benefit for a healthy person is modest.", "highlight": "Marine omega-3 supplementation lowers risk for myocardial infarction, CHD death, total CHD, CVD death, and total CVD, even after exclusion of REDUCE-IT"}, {"title": "Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease", "authors": "Abdelhamid AS, Brown TJ, Brainard JS, et al.", "year": 2020, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD003177.pub5", "pmid": "32114706", "pmcid": "PMC7049091", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7049091/", "type": "systematic review", "summary": "This Cochrane review analyzed 86 randomized trials (162,796 participants) lasting at least a year. Long-chain omega-3 had little or no effect on all-cause mortality (RR 0.97) or total cardiovascular events (RR 0.96), may slightly reduce coronary events (NNT 167), and cut triglycerides by about 15%. It is the most sober read of the evidence: fish oil is a triglyceride tool, not a broad heart-protection pill.", "highlight": "increasing LCn3 slightly reduces risk of coronary heart disease mortality and events, and reduces serum triglycerides"}, {"title": "Omega-3 Fatty Acids for the Management of Hypertriglyceridemia: A Science Advisory From the American Heart Association", "authors": "Skulas-Ray AC, Wilson PWF, Harris WS, et al.", "year": 2019, "journal": "Circulation", "doi": "10.1161/CIR.0000000000000709", "pmid": "31422671", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31422671/", "type": "guideline", "summary": "This American Heart Association science advisory reviews trial data on prescription-strength omega-3 (about 4 g/day EPA+DHA or EPA alone) for high triglycerides. At 4 g/day, omega-3 lowers very high triglycerides by 30% or more, and EPA-only cut major cardiovascular events by 25% in REDUCE-IT among statin-treated high-risk patients. These results apply to pharmacological doses in people with high triglycerides, not to a typical 1 g fish oil capsule.", "highlight": "In treatment of very high triglycerides with 4 g/d, EPA+DHA agents reduce triglycerides by ≥30%"}]}, {"id": "d3", "label": "Vitamin D3", "title": "Vitamin D3", "tier": "supplements", "group": null, "blurb": "Blueprint: 2,000 IU in the Essential Capsules.", "sources": [{"title": "Vitamin D Supplements and Prevention of Cancer and Cardiovascular Disease", "authors": "Manson JE, Cook NR, Lee IM, et al.", "year": 2019, "journal": "The New England Journal of Medicine", "doi": "10.1056/NEJMoa1809944", "pmid": "30415629", "pmcid": "PMC6425757", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6425757/", "type": "RCT", "summary": "The VITAL trial randomized 25,871 US adults aged 50+ (men) or 55+ (women) to 2,000 IU/day vitamin D3 or placebo, following them for a median of 5.3 years. Vitamin D3 did not lower invasive cancer (HR 0.96) or major cardiovascular events (HR 0.97), and all-cause mortality was unchanged (HR 0.99), though cancer death showed a non-significant trend (HR 0.83). Participants were mostly not vitamin D deficient, so the results argue against routine D3 for disease prevention in replete adults rather than against correcting a deficiency.", "highlight": "Supplementation with vitamin D did not result in a lower incidence of invasive cancer or cardiovascular events than placebo."}]}, {"id": "b12", "label": "Vitamin B12", "title": "Vitamin B12", "tier": "supplements", "group": null, "blurb": "Blueprint: 125 mcg methylcobalamin in the Essential Capsules.", "sources": []}, {"id": "bcomplex", "label": "B vitamins + folate", "title": "B vitamins & folate", "tier": "supplements", "group": null, "blurb": "Blueprint: B1, B2, B3, B5, B6, biotin and methylfolate in the Essential Capsules.", "sources": []}, {"id": "vitaminc", "label": "Vitamin C", "title": "Vitamin C", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": []}, {"id": "vitamine", "label": "Vitamin E", "title": "Vitamin E", "tier": "supplements", "group": null, "blurb": "Blueprint: 67 mg d-alpha-tocopherol in the Essential Capsules.", "sources": []}, {"id": "vitamink", "label": "Vitamin K1 + K2", "title": "Vitamin K1 + K2", "tier": "supplements", "group": null, "blurb": "Blueprint: K1, K2 MK-4 and K2 MK-7 in the Advanced Antioxidants softgel.", "sources": [{"title": "Effect of vitamin K on bone mineral density and fractures in adults: an updated systematic review and meta-analysis of randomised controlled trials", "authors": "Mott A, Bradley T, Wright K, et al.", "year": 2019, "journal": "Osteoporosis International", "doi": "10.1007/s00198-019-04949-0", "pmid": "31076817", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31076817/", "type": "meta-analysis", "summary": "This updated systematic review identified 36 randomized trials of oral vitamin K (K1 and K2 forms) on bone mineral density and fractures in adults. In postmenopausal or osteoporotic patients, vitamin K was linked to lower odds of clinical fracture (OR 0.72), but this weakened to a non-significant OR 0.76 when restricted to low risk-of-bias trials, and vertebral fractures were unchanged. The authors conclude there is no evidence vitamin K improves bone density and the fracture signal is insufficient to confirm.", "highlight": "For post-menopausal or osteoporotic patients, there is no evidence that vitamin K affects bone mineral density or vertebral fractures"}, {"title": "Three-year low-dose menaquinone-7 supplementation helps decrease bone loss in healthy postmenopausal women", "authors": "Knapen MH, Drummen NE, Smit E, et al.", "year": 2013, "journal": "Osteoporosis International", "doi": "10.1007/s00198-013-2325-6", "pmid": "23525894", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23525894/", "type": "RCT", "summary": "This 3-year randomized placebo-controlled trial gave 244 healthy postmenopausal women 180 µg/day of vitamin K2 as MK-7 or placebo, measuring bone density by DXA. MK-7 improved vitamin K status and slowed the age-related decline in bone density and bone mineral content at the lumbar spine and femoral neck, but not at the total hip. It is a single trial in one population measuring bone density rather than fractures, so it supports but does not prove a fracture benefit.", "highlight": "MK-7 intake significantly improved vitamin K status and decreased the age-related decline in BMC and BMD at the lumbar spine and femoral neck"}, {"title": "Vitamin K supplementation and vascular calcification: a systematic review and meta-analysis of randomized controlled trials", "authors": "Li T, Wang Y, Tu WP", "year": 2023, "journal": "Frontiers in Nutrition", "doi": "10.3389/fnut.2023.1115069", "pmid": "37252246", "pmcid": "PMC10218696", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10218696/", "type": "meta-analysis", "summary": "This meta-analysis pooled 14 randomized trials (1,533 patients, many with kidney or cardiovascular disease) testing vitamin K supplementation on vascular calcification. Vitamin K slowed coronary artery calcification score progression (mean difference -17.37, p = 0.04) and lowered dp-ucMGP, a marker of poor vitamin K status, with no excess adverse events. The calcification effect was small and borderline, came largely from patient populations, and the authors call for more rigorous trials.", "highlight": "VK supplementation has a significant effect on CAC scores, slowing down the progression of CAC"}]}, {"id": "magnesium", "label": "Magnesium", "title": "Magnesium", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": []}, {"id": "zinccopper", "label": "Zinc + Copper", "title": "Zinc + copper", "tier": "supplements", "group": null, "blurb": "Blueprint: 15 mg zinc bisglycinate in the Essential Capsules. Copper is my addition: long-term zinc without copper can cause copper deficiency.", "sources": []}, {"id": "selenium", "label": "Selenium", "title": "Selenium", "tier": "supplements", "group": null, "blurb": "Blueprint: 28 mcg selenomethionine in the Essential Capsules.", "sources": []}, {"id": "iodine", "label": "Iodine", "title": "Iodine", "tier": "supplements", "group": null, "blurb": "Blueprint: 200 mcg in the Essential Capsules.", "sources": []}, {"id": "calcium_mn", "label": "Calcium + Manganese", "title": "Calcium & manganese", "tier": "supplements", "group": null, "blurb": "Blueprint: small doses (50 mg calcium, 1 mg manganese) in the Essential Capsules.", "sources": []}, {"id": "boron", "label": "Boron", "title": "Boron", "tier": "supplements", "group": null, "blurb": "Blueprint: 3 mg boron glycinate in the Essential Capsules.", "sources": []}, {"id": "lithium", "label": "Lithium (1 mg)", "title": "Low-dose lithium", "tier": "supplements", "group": null, "blurb": "Blueprint: 1 mg lithium orotate in the Essential Capsules. A trace dose, hundreds of times below psychiatric doses.", "sources": []}, {"id": "caakg", "label": "CaAKG", "title": "Calcium alpha-ketoglutarate (CaAKG)", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Alpha-Ketoglutarate, an Endogenous Metabolite, Extends Lifespan and Compresses Morbidity in Aging Mice", "authors": "Asadi Shahmirzadi A, Edgar D, Liao CY, et al.", "year": 2020, "journal": "Cell Metabolism", "doi": "10.1016/j.cmet.2020.08.004", "pmid": "32877690", "pmcid": "PMC8508957", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8508957/", "type": "animal study", "summary": "This study fed middle-aged C57BL/6 mice calcium alpha-ketoglutarate (CaAKG) in their diet and tracked lifespan alongside longitudinal frailty and healthspan measures. CaAKG extended lifespan, reduced frailty and lowered systemic inflammatory cytokines, an effect the authors tie to induction of IL-10. These are mouse results only; no human lifespan or hard-outcome data exist for CaAKG.", "highlight": "We find that CaAKG promotes a longer, healthier life associated with a decrease in levels of systemic inflammatory cytokines."}, {"title": "Rejuvant, a potential life-extending compound formulation with alpha-ketoglutarate and vitamins, conferred an average 8 year reduction in biological aging, after an average of 7 months of use, in the TruAge DNA methylation test", "authors": "Demidenko O, Barardo D, Budovskii V, et al.", "year": 2021, "journal": "Aging", "doi": "10.18632/aging.203736", "pmid": "34847066", "pmcid": "PMC8660611", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8660611/", "type": "cohort", "summary": "This retrospective analysis looked at DNA methylation age in 42 people who took Rejuvant, a CaAKG-plus-vitamin formulation, for an average of 7 months. Their measured biological age fell by an average of about 8 years. There was no placebo or control group, the sample was small and self-selected, and the authors themselves state placebo-controlled testing is required, so this is very weak evidence.", "highlight": "individuals showed an average decrease in biological aging of 8 years (p-value=6.538x10-12)"}, {"title": "Alpha-ketoglutarate supplementation and BiologicaL agE in middle-aged adults (ABLE)-intervention study protocol", "authors": "Sandalova E, Goh J, Lim ZX, et al.", "year": 2023, "journal": "GeroScience", "doi": "10.1007/s11357-023-00813-6", "pmid": "37217632", "pmcid": "PMC10643463", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10643463/", "type": "RCT", "summary": "This paper describes the ABLE trial, a double-blind placebo-controlled RCT of 1 g/day sustained-release CaAKG for 6 months in 120 healthy 40-60-year-olds whose DNA methylation age exceeds their chronological age. The primary outcome is change in DNA methylation age, with secondary outcomes including inflammation, strength, arterial stiffness and aerobic capacity. It is a protocol, not results, and its existence underlines that properly controlled human evidence for CaAKG is still pending.", "highlight": "Alpha-Ketoglutarate (AKG) has been studied widely in model animals, but there are few studies testing its geroprotective properties in humans."}]}, {"id": "glutathione", "label": "Glutathione", "title": "Glutathione", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": []}, {"id": "lysine", "label": "Lysine", "title": "L-lysine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": []}, {"id": "arginine", "label": "L-arginine", "title": "L-arginine", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": []}, {"id": "theanine", "label": "L-theanine", "title": "L-theanine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": []}, {"id": "coq10", "label": "CoQ10", "title": "CoQ10 (ubiquinol)", "tier": "supplements", "group": null, "blurb": "Blueprint: 50 mg ubiquinol in the Essential Capsules.", "sources": []}, {"id": "spermidine", "label": "Spermidine", "title": "Spermidine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Essential Capsules.", "sources": []}, {"id": "broccoli", "label": "Broccoli extract", "title": "Broccoli seed extract (sulforaphane)", "tier": "supplements", "group": null, "blurb": "Blueprint: 200 mg broccoli seed extract (20 mg glucoraphanin) in the Essential Capsules.", "sources": []}, {"id": "lutein_lycopene", "label": "Lutein + Lycopene", "title": "Lutein & lycopene", "tier": "supplements", "group": null, "blurb": "Blueprint: 15 mg each in the Advanced Antioxidants softgel.", "sources": [{"title": "The Effect of Lutein/Zeaxanthin Intake on Human Macular Pigment Optical Density: A Systematic Review and Meta-Analysis", "authors": "Wilson LM, Tharmarajah S, Jia Y, et al.", "year": 2021, "journal": "Advances in Nutrition", "doi": "10.1093/advances/nmab071", "pmid": "34157098", "pmcid": "PMC8634499", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8634499/", "type": "meta-analysis", "summary": "This systematic review and meta-analysis pooled 46 studies (3,189 adults with healthy eyes) testing lutein/zeaxanthin from supplements or food on macular pigment optical density (MPOD). Intakes under 5 mg/day showed no significant change, while 5 to under 20 mg/day raised MPOD by 0.04 units and 20 mg/day or more raised it by 0.11 units over 3-12 months. MPOD is a surrogate marker, and the authors note it is still unclear what dose or duration produces a clinically meaningful change in vision.", "highlight": "MPOD increased with lutein/zeaxanthin intake, particularly at higher doses, among adults with healthy eyes."}, {"title": "Tomato and lycopene supplementation and cardiovascular risk factors: A systematic review and meta-analysis", "authors": "Cheng HM, Koutsidis G, Lodge JK, et al.", "year": 2017, "journal": "Atherosclerosis", "doi": "10.1016/j.atherosclerosis.2017.01.009", "pmid": "28129549", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/28129549/", "type": "meta-analysis", "summary": "This meta-analysis pooled 21 intervention trials in adults testing tomato products or lycopene supplements on blood lipids, endothelial function, blood pressure and inflammation markers. Lycopene supplements lowered systolic blood pressure by 5.66 mmHg, while tomato products lowered LDL cholesterol by 0.22 mmol/L and improved flow-mediated dilation by 2.53%. Most other outcomes were unchanged, the trials were small and short, and these are risk-factor changes, not proof of fewer heart attacks or strokes.", "highlight": "increasing the intake of these has positive effects on blood lipids, blood pressure and endothelial function"}]}, {"id": "garlic", "label": "Garlic", "title": "Garlic", "tier": "supplements", "group": null, "blurb": "My addition as a supplement; Bryan eats garlic in his Super Veggie meal.", "sources": []}, {"id": "chlorella", "label": "Chlorella", "title": "Chlorella", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": []}, {"id": "fenugreek", "label": "Fenugreek", "title": "Fenugreek", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": []}, {"id": "turmeric", "label": "Turmeric", "title": "Turmeric (curcumin)", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack. Take with black pepper and fat for absorption.", "sources": []}, {"id": "legs", "label": "Legs", "title": "Leg day", "tier": "weekly", "group": null, "blurb": "Squats, lunges, deadlifts, step-ups. Once a week, hard.", "sources": [{"title": "Association between muscular strength and mortality in men: prospective cohort study", "authors": "Ruiz JR, Sui X, Lobelo F, et al.", "year": 2008, "journal": "BMJ (Clinical research ed.)", "doi": "10.1136/bmj.a439", "pmid": "18595904", "pmcid": "PMC2453303", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2453303/", "type": "cohort", "summary": "Prospective cohort of 8,762 men aged 20-80 in the Aerobics Center Longitudinal Study, with strength measured by 1-rep max leg press and bench press and followed for about 19 years. Men in the middle and top thirds of strength had roughly 23-28% lower all-cause mortality than the weakest third, and the link held after adjusting for cardiorespiratory fitness. It is observational, men only, and combines leg and upper-body strength, so it shows strength tracks with survival rather than proving leg training causes it.", "highlight": "Muscular strength is inversely and independently associated with death from all causes and cancer in men"}, {"title": "Exercise for preventing falls in older people living in the community", "authors": "Sherrington C, Fairhall NJ, Wallbank GK, et al.", "year": 2019, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD012424.pub2", "pmid": "30703272", "pmcid": "PMC6360922", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6360922/", "type": "systematic review", "summary": "Cochrane review of 108 randomised trials with 23,407 community-dwelling adults aged 60 and over, testing exercise programmes for fall prevention. Exercise cut the rate of falls by 23% (high-certainty evidence), and programmes combining balance and functional work with resistance training cut falls by about 34%. Resistance training alone had uncertain effects on falls, so leg strength work pays off most when paired with balance training.", "highlight": "Exercise programmes reduce the rate of falls and the number of people experiencing falls in older people living in the community"}, {"title": "Progressive resistance strength training for improving physical function in older adults", "authors": "Liu CJ, Latham NK", "year": 2009, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD002759.pub2", "pmid": "19588334", "pmcid": "PMC4324332", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4324332/", "type": "systematic review", "summary": "Cochrane review of 121 randomised trials with 6,700 older adults doing progressive resistance training, usually 2-3 times a week at high intensity. Training produced a large gain in muscle strength (SMD 0.84) and a moderate-to-large improvement in getting out of a chair, with a smaller gain in gait speed. Effects on broad physical ability were small and adverse events were poorly reported, so the clearest benefit is strength and basic lower-body function.", "highlight": "This review provides evidence that PRT is an effective intervention for improving physical functioning in older people"}]}, {"id": "armsback", "label": "Arms & Back", "title": "Arms & back day", "tier": "weekly", "group": null, "blurb": "Rows, pull-ups, curls, presses.", "sources": [{"title": "Muscle-strengthening activities are associated with lower risk and mortality in major non-communicable diseases: a systematic review and meta-analysis of cohort studies", "authors": "Momma H, Kawakami R, Honda T, et al.", "year": 2022, "journal": "British journal of sports medicine", "doi": "10.1136/bjsports-2021-105061", "pmid": "35228201", "pmcid": "PMC9209691", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9209691/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 16 prospective cohort studies on muscle-strengthening activity and disease and death, independent of aerobic activity. Muscle-strengthening was linked to 10-17% lower risk of all-cause mortality, cardiovascular disease, total cancer and diabetes, with the biggest benefit at about 30-60 minutes per week. The curve was J-shaped, so more than an hour or so a week showed no added mortality benefit, and all included data are observational.", "highlight": "Muscle-strengthening activities were associated with a 10-17% lower risk of all-cause mortality, cardiovascular disease (CVD), total cancer, diabetes and lung cancer"}, {"title": "Dose-response relationship between weekly resistance training volume and increases in muscle mass: A systematic review and meta-analysis", "authors": "Schoenfeld BJ, Ogborn D, Krieger JW", "year": 2017, "journal": "Journal of sports sciences", "doi": "10.1080/02640414.2016.1210197", "pmid": "27433992", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/27433992/", "type": "meta-analysis", "summary": "Meta-regression of 15 training studies (34 treatment groups) testing how weekly resistance training volume affects muscle growth. Each additional weekly set was associated with about 0.37% more muscle gain, and higher-volume groups gained about 3.9% more than lower-volume groups. The studies were small and short, and the three-level comparison (under 5, 5-9, 10+ sets per muscle) only trended toward significance.", "highlight": "The findings indicate a graded dose-response relationship whereby increases in RT volume produce greater gains in muscle hypertrophy"}, {"title": "Effects of Resistance Training Frequency on Measures of Muscle Hypertrophy: A Systematic Review and Meta-Analysis", "authors": "Schoenfeld BJ, Ogborn D, Krieger JW", "year": 2016, "journal": "Sports medicine (Auckland, N.Z.)", "doi": "10.1007/s40279-016-0543-8", "pmid": "27102172", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/27102172/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 10 trials comparing how often a muscle group is trained per week, with volume equated. Training a muscle twice a week produced a larger hypertrophy effect size than once a week (0.49 vs 0.30). Whether three times a week beats twice is unknown, and the evidence base is small, but hitting arms and back at least twice weekly is a reasonable target.", "highlight": "frequencies of training twice a week promote superior hypertrophic outcomes to once a week"}]}, {"id": "fullbody", "label": "Full body", "title": "Full-body workout", "tier": "weekly", "group": null, "blurb": "One session that hits everything.", "sources": [{"title": "Efficacy of Split Versus Full-Body Resistance Training on Strength and Muscle Growth: A Systematic Review With Meta-Analysis", "authors": "Ramos-Campo DJ, Benito-Peinado PJ, Andreu-Caravaca L, et al.", "year": 2024, "journal": "Journal of strength and conditioning research", "doi": "10.1519/JSC.0000000000004774", "pmid": "38595233", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/38595233/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 14 studies (392 healthy adults) comparing split routines with full-body routines. Strength gains in bench press and lower limbs, and muscle growth in arms, thighs and lean mass, were statistically similar between the two approaches. The studies were small and volume was matched, so the practical point is that full-body sessions work as well as splits and the choice can rest on schedule and preference.", "highlight": "does not significantly impact either strength gains or muscle hypertrophy when volume is equated"}, {"title": "American College of Sports Medicine position stand. Progression models in resistance training for healthy adults", "authors": "American College of Sports Medicine", "year": 2009, "journal": "Medicine and science in sports and exercise", "doi": "10.1249/MSS.0b013e3181915670", "pmid": "19204579", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/19204579/", "type": "guideline", "summary": "ACSM position stand setting out evidence-based progression models for resistance training in healthy adults. It recommends 2-3 sessions a week for novices, 8-12 rep loads to start, large-muscle and multi-joint exercises before small ones, and emphasis on multi-joint lifts involving the whole body. It is a consensus document built largely on short training studies, and it is now dated (2009), though its core advice has held up.", "highlight": "It is also recommended that emphasis be placed on multiple-joint exercises especially those involving the total body"}, {"title": "World Health Organization 2020 guidelines on physical activity and sedentary behaviour", "authors": "Bull FC, Al-Ansari SS, Biddle S, et al.", "year": 2020, "journal": "British journal of sports medicine", "doi": "10.1136/bjsports-2020-102955", "pmid": "33239350", "pmcid": "PMC7719906", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7719906/", "type": "guideline", "summary": "WHO 2020 physical activity guidelines, built by an expert group from updated systematic reviews across all ages and several special populations. Adults are advised to do 150-300 minutes of moderate aerobic activity weekly plus muscle-strengthening activity involving all major muscle groups on two or more days. This is a population-level minimum rather than an optimal program, but a full-body session twice a week satisfies the strength part in one go.", "highlight": "These guidelines highlight the importance of regularly undertaking both aerobic and muscle strengthening activities"}]}, {"id": "run5k", "label": "Long run 5K+", "title": "Long run, 5K+", "tier": "weekly", "group": null, "blurb": "One easy long run a week of at least 5 km.", "sources": [{"title": "Is running associated with a lower risk of all-cause, cardiovascular and cancer mortality, and is the more the better? A systematic review and meta-analysis", "authors": "Pedisic Z, Shrestha N, Kovalchik S, et al.", "year": 2020, "journal": "British journal of sports medicine", "doi": "10.1136/bjsports-2018-100493", "pmid": "31685526", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31685526/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 14 studies from six prospective cohorts with 232,149 participants and 25,951 deaths. Any running was associated with 27% lower all-cause, 30% lower cardiovascular and 23% lower cancer mortality compared with no running. No dose-response was found for frequency, duration, pace or volume, so a single weekly run captures much of the benefit and more is not clearly better.", "highlight": "Any amount of running, even just once a week, is better than no running"}, {"title": "Leisure-time running reduces all-cause and cardiovascular mortality risk", "authors": "Lee DC, Pate RR, Lavie CJ, et al.", "year": 2014, "journal": "Journal of the American College of Cardiology", "doi": "10.1016/j.jacc.2014.04.058", "pmid": "25082581", "pmcid": "PMC4131752", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4131752/", "type": "cohort", "summary": "Prospective cohort of 55,137 adults in the Aerobics Center Longitudinal Study followed for a mean of 15 years. Runners had 30% lower all-cause and 45% lower cardiovascular mortality than non-runners, about 3 extra years of life expectancy, and even under 6 miles a week was enough. It is observational and runners may differ from non-runners in other ways, but persistent runners over time saw the largest benefit.", "highlight": "Compared with nonrunners, runners had 30% and 45% lower adjusted risks of all-cause and cardiovascular mortality, respectively, with a 3-year life expectancy benefit"}, {"title": "Cardiorespiratory fitness as a quantitative predictor of all-cause mortality and cardiovascular events in healthy men and women: a meta-analysis", "authors": "Kodama S, Saito K, Tanaka S, et al.", "year": 2009, "journal": "JAMA", "doi": "10.1001/jama.2009.681", "pmid": "19454641", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/19454641/", "type": "meta-analysis", "summary": "Meta-analysis of 33 cohort studies with about 103,000 healthy adults linking measured cardiorespiratory fitness to mortality and heart disease. Each 1-MET higher fitness level, roughly a 1 km/h faster running speed, was associated with 13% lower all-cause mortality and 15% lower cardiovascular events. Low-fit people (under 7.9 METs) had 70% higher mortality than high-fit people, so regular running is a practical way to move up the fitness scale.", "highlight": "Better CRF was associated with lower risk of all-cause mortality and CHD/CVD"}]}, {"id": "zone2", "label": "7 hrs Zone 2", "title": "7 hours of Zone 2", "tier": "weekly", "group": null, "blurb": "Seven hours a week of easy, conversational cardio (about 60–70% of max heart rate): you can talk, but not sing.", "sources": [{"title": "Leisure time physical activity and mortality: a detailed pooled analysis of the dose-response relationship", "authors": "Arem H, Moore SC, Patel A, Hartge P, et al.", "year": 2015, "journal": "JAMA Internal Medicine", "doi": "10.1001/jamainternmed.2015.0533", "pmid": "25844730", "pmcid": "PMC4451435", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4451435/", "type": "cohort", "summary": "This pooled six US and European cohorts covering 661,137 adults and 116,686 deaths over a median of 14 years of follow-up. Meeting the 150-minute moderate-activity minimum was linked to 31% lower mortality, with the benefit leveling off at 3-5 times that amount (39% lower) and no sign of harm at 10 times or more. It is observational and self-reported, so fitter, healthier people may simply exercise more, but the dose-response shape is consistent.", "highlight": "An upper threshold for mortality benefit occurred at 3 to 5 times the physical activity recommendation"}, {"title": "Long-Term Leisure-Time Physical Activity Intensity and All-Cause and Cause-Specific Mortality: A Prospective Cohort of US Adults", "authors": "Lee DH, Rezende LFM, Joh HK, Keum N, et al.", "year": 2022, "journal": "Circulation", "doi": "10.1161/CIRCULATIONAHA.121.058162", "pmid": "35876019", "pmcid": "PMC9378548", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9378548/", "type": "cohort", "summary": "This study followed 116,221 US nurses and health professionals for 30 years, with activity reassessed up to 15 times, and recorded 47,596 deaths. Meeting the moderate-activity guideline (150-299 min/week) was tied to 19-25% lower mortality, and the near-maximum benefit came at about 300-600 min/week of moderate activity. Above that there was no clear extra benefit or harm, and the cohort is mostly white health professionals, so causation and generalizability are limited.", "highlight": "Meeting the long-term leisure-time MPA guideline (150-299 min/wk) was similarly associated with lower mortality"}, {"title": "Much Ado About Zone 2: A Narrative Review Assessing the Efficacy of Zone 2 Training for Improving Mitochondrial Capacity and Cardiorespiratory Fitness in the General Population", "authors": "Storoschuk KL, Moran-MacDonald A, Gibala MJ, Gurd BJ", "year": 2025, "journal": "Sports Medicine", "doi": "10.1007/s40279-025-02261-y", "pmid": "40560504", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/40560504/", "type": "review", "summary": "This narrative review examines the training-study evidence behind the popular claim that Zone 2 (below lactate threshold) is the best intensity for mitochondria and fat oxidation. It concludes the evidence does not support Zone 2 as optimal, and that higher intensities matter more when weekly training time is limited. Zone 2 is still useful as volume, but the specific mitochondrial hype comes mostly from observations of elite athletes, not trials in ordinary people.", "highlight": "We conclude that current evidence does not support Zone 2 training as the optimal intensity for improving mitochondrial or fatty acid oxidative capacity."}]}, {"id": "zone5", "label": "Zone 5 training", "title": "Zone 5 training (VO2 max)", "tier": "weekly", "group": null, "blurb": "One session a week of near-max intervals. The best-studied version is the Norwegian 4×4 method from NTNU: after a warm-up, 4 minutes at 90–95% of max heart rate, then 3 minutes of easy recovery, repeated 4 times (about 40 minutes in all). It is the protocol most consistently shown to raise VO2 max.", "sources": [{"title": "Superior cardiovascular effect of aerobic interval training versus moderate continuous training in heart failure patients: a randomized study", "authors": "Wisløff U, Støylen A, Loennechen JP, Bruvold M, et al.", "year": 2007, "journal": "Circulation", "doi": "10.1161/CIRCULATIONAHA.106.675041", "pmid": "17548726", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/17548726/", "type": "RCT", "summary": "This trial randomized 27 elderly patients with post-heart-attack heart failure to 4x4-minute intervals at 95% of peak heart rate, moderate continuous training at 70%, or usual care, three times a week for 12 weeks. VO2peak rose 46% with intervals versus 14% with moderate training, and only the interval group showed reverse remodeling of the heart. It is the founding study of the Norwegian 4x4, but it was very small and a much larger later trial (SMARTEX-HF) did not confirm intervals were superior.", "highlight": "VO2peak increased more with aerobic interval training than moderate continuous training (46% versus 14%, P<0.001)"}, {"title": "Effect of exercise training for five years on all cause mortality in older adults-the Generation 100 study: randomised controlled trial", "authors": "Stensvold D, Viken H, Steinshamn SL, Dalen H, et al.", "year": 2020, "journal": "BMJ", "doi": "10.1136/bmj.m3485", "pmid": "33028588", "pmcid": "PMC7539760", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7539760/", "type": "RCT", "summary": "Generation 100 randomized 1,567 Norwegians aged 70-77 to twice-weekly 4x4 intervals at about 90% of peak heart rate, moderate continuous training, or national activity guidelines for five years. Overall mortality did not differ between exercise and control groups, though HIIT trended lower (HR 0.63 vs control; 0.51 vs moderate training, confidence intervals crossing 1). The result is a trend, not proof, and the participants were already healthy and active, which made differences hard to detect.", "highlight": "we observed a lower all cause mortality trend after HIIT compared with controls and MICT"}, {"title": "Effectiveness of High-Intensity Interval Training (HIT) and Continuous Endurance Training for VO2max Improvements: A Systematic Review and Meta-Analysis of Controlled Trials", "authors": "Milanović Z, Sporiš G, Weston M", "year": 2015, "journal": "Sports Medicine", "doi": "10.1007/s40279-015-0365-0", "pmid": "26243014", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/26243014/", "type": "meta-analysis", "summary": "This meta-analysis pooled 28 controlled trials (723 healthy adults aged 18-45) comparing interval training, continuous endurance training and no exercise on VO2max. Both raised VO2max substantially (about 5.5 and 4.9 mL/kg/min versus controls), with intervals adding a small extra gain of about 1.2 mL/kg/min over continuous training. The edge for intervals is real but small, and the trials were short and mostly in young people.", "highlight": "Endurance training and HIT both elicit large improvements in the VO2max of healthy, young to middle-aged adults"}]}, {"id": "sprints", "label": "Sprints", "title": "Sprints", "tier": "weekly", "group": null, "blurb": "One sprint session a week: 4–8 all-out efforts of 10–30 seconds with full recovery between.", "sources": [{"title": "Number of Sprint Repetitions in a Sprint Interval Training Session Does Not Moderate Improvements in V̇O2max With Training: A Systematic Review and Meta-Analysis", "authors": "Hutchinson M, Kinghorn DJ, Hall ECR, Metcalfe RS, et al.", "year": 2026, "journal": "Scandinavian Journal of Medicine & Science in Sports", "doi": "10.1111/sms.70347", "pmid": "42477971", "pmcid": "PMC13385658", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13385658/", "type": "meta-analysis", "summary": "This meta-analysis pooled 93 trials from 78 studies (1,188 mostly untrained people) of at least two weeks of all-out cycling sprint training. Sprint interval training raised VO2max by about 8.3%, and adding more sprints per session made essentially no difference. A few sprints per session is enough for fitness, but the data come from cycle-ergometer studies in untrained people, so gains in already-fit people will be smaller.", "highlight": "SIT produced an 8.3% increase in V̇O2max (95% CrI: 7.0 to 9.5%)."}, {"title": "Twelve Weeks of Sprint Interval Training Improves Indices of Cardiometabolic Health Similar to Traditional Endurance Training despite a Five-Fold Lower Exercise Volume and Time Commitment", "authors": "Gillen JB, Martin BJ, MacInnis MJ, Skelly LE, et al.", "year": 2016, "journal": "PLoS One", "doi": "10.1371/journal.pone.0154075", "pmid": "27115137", "pmcid": "PMC4846072", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4846072/", "type": "RCT", "summary": "Sedentary men were randomized to 12 weeks of sprint intervals (3 x 20-second all-out sprints, 10 minutes total), 45 minutes of moderate continuous cycling, or no training, three times a week. Both training groups improved peak oxygen uptake by 19% and improved insulin sensitivity and muscle mitochondrial content to a similar degree. The trial is small (25 men, 9 in the sprint group), so it shows sprints can match longer cardio on these markers, not that they beat it.", "highlight": "Peak oxygen uptake increased after training by 19% in both groups"}, {"title": "Skeletal muscle power: a critical determinant of physical functioning in older adults", "authors": "Reid KF, Fielding RA", "year": 2012, "journal": "Exercise and Sport Sciences Reviews", "doi": "10.1097/JES.0b013e31823b5f13", "pmid": "22016147", "pmcid": "PMC3245773", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3245773/", "type": "review", "summary": "This review summarizes cross-sectional, longitudinal and training studies on muscle power (force times speed) in older adults. It reports that power falls earlier and faster with age than strength and predicts functional limitations better than strength does. It supports keeping some fast, explosive work like sprints as you age, but it is a narrative review and does not test sprinting itself.", "highlight": "Muscle power declines earlier and more precipitously with advancing age compared with muscle strength."}]}, {"id": "social", "label": "Social time", "title": "Social time", "tier": "weekly", "group": null, "blurb": "Real time with friends or family, in person, every week.", "sources": [{"title": "Social relationships and mortality risk: a meta-analytic review", "authors": "Holt-Lunstad J, Smith TB, Layton JB", "year": 2010, "journal": "PLoS medicine", "doi": "10.1371/journal.pmed.1000316", "pmid": "20668659", "pmcid": "PMC2910600", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2910600/", "type": "meta-analysis", "summary": "Meta-analysis of 148 prospective studies (308,849 people, average follow-up about 7.5 years) on social relationships and mortality. People with stronger social relationships had 50% greater odds of survival (OR 1.50), and complex measures of social integration showed an even larger effect (OR 1.91). The authors compare the effect to smoking and exceeding obesity and inactivity, but these are observational data that cannot fully separate cause from confounding by health.", "highlight": "The influence of social relationships on risk for mortality is comparable with well-established risk factors for mortality"}, {"title": "Loneliness and social isolation as risk factors for mortality: a meta-analytic review", "authors": "Holt-Lunstad J, Smith TB, Baker M, et al.", "year": 2015, "journal": "Perspectives on psychological science : a journal of the Association for Psychological Science", "doi": "10.1177/1745691614568352", "pmid": "25910392", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25910392/", "type": "meta-analysis", "summary": "Meta-analysis of prospective studies (70 studies, about 3.4 million people) on objective social isolation, subjective loneliness and living alone as predictors of death. After adjusting for confounders, social isolation raised the odds of death by 29%, loneliness by 26%, and living alone by 32%. Effects were stronger in people under 65, and like all such data it is observational, but it shows both being alone and feeling alone carry risk.", "highlight": "social isolation odds ratio (OR) = 1.29, loneliness OR = 1.26, and living alone OR = 1.32"}, {"title": "Loneliness and social isolation as risk factors for coronary heart disease and stroke: systematic review and meta-analysis of longitudinal observational studies", "authors": "Valtorta NK, Kanaan M, Gilbody S, et al.", "year": 2016, "journal": "Heart (British Cardiac Society)", "doi": "10.1136/heartjnl-2015-308790", "pmid": "27091846", "pmcid": "PMC4941172", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4941172/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 16 longitudinal datasets (4,628 coronary heart disease and 3,002 stroke events over 3-21 years) in high-income countries. Poor social relationships were linked to a 29% higher risk of coronary heart disease (RR 1.29) and a 32% higher risk of stroke (RR 1.32). Confidence intervals were wide and it is unknown whether interventions that reduce loneliness lower these risks, but it points to cardiovascular disease as one pathway.", "highlight": "Poor social relationships were associated with a 29% increase in risk of incident CHD"}]}, {"id": "nature", "label": "Time in nature", "title": "Time in nature", "tier": "weekly", "group": null, "blurb": "About two hours a week in parks, forests, beaches or trails. It can be split up across the week.", "sources": [{"title": "Spending at least 120 minutes a week in nature is associated with good health and wellbeing", "authors": "White MP, Alcock I, Grellier J, et al.", "year": 2019, "journal": "Scientific reports", "doi": "10.1038/s41598-019-44097-3", "pmid": "31197192", "pmcid": "PMC6565732", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6565732/", "type": "cohort", "summary": "Cross-sectional analysis of 19,806 adults from England's nationally representative MENE survey, relating time spent in nature in the past 7 days to self-reported health and wellbeing. People with at least 120 minutes of nature contact per week were more likely to report good health (OR 1.59) and high wellbeing (OR 1.23), with benefits peaking at 200-300 minutes and no gain below 120. It is cross-sectional and self-reported, so reverse causation is possible, but the 120 min/week threshold is a practical target and can be split across several visits.", "highlight": "Compared to no nature contact last week, the likelihood of reporting good health or high well-being became significantly greater with contact"}, {"title": "The health benefits of the great outdoors: A systematic review and meta-analysis of greenspace exposure and health outcomes", "authors": "Twohig-Bennett C, Jones A", "year": 2018, "journal": "Environmental research", "doi": "10.1016/j.envres.2018.06.030", "pmid": "29982151", "pmcid": "PMC6562165", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6562165/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 143 studies (103 observational, 40 interventional) covering about 100 health outcomes and greenspace exposure. Greater greenspace exposure was associated with lower cortisol, heart rate and diastolic blood pressure, 28% lower type 2 diabetes risk, and lower all-cause (OR 0.69) and cardiovascular mortality. Many pooled results came from poor-quality, highly heterogeneous studies, so the direction is consistent but the effect sizes are uncertain.", "highlight": "Greenspace exposure is associated with numerous health benefits in intervention and observational studies"}, {"title": "Green spaces and mortality: a systematic review and meta-analysis of cohort studies", "authors": "Rojas-Rueda D, Nieuwenhuijsen MJ, Gascon M, et al.", "year": 2019, "journal": "The Lancet. Planetary health", "doi": "10.1016/S2542-5196(19)30215-3", "pmid": "31777338", "pmcid": "PMC6873641", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6873641/", "type": "meta-analysis", "summary": "WHO-funded meta-analysis of 9 cohort studies (over 8.3 million people in seven countries) relating satellite-measured greenness around the home (NDVI) to all-cause mortality. Each 0.1 increase in greenness within 500 m of home was associated with a 4% lower risk of death (HR 0.96). This measures living near green space, not deliberately spending time in it, and heterogeneity was high, so it supports the general idea rather than a specific weekly dose.", "highlight": "We found evidence of an inverse association between surrounding greenness and all-cause mortality"}]}, {"id": "fish", "label": "Fish", "title": "Fish", "tier": "weekly", "group": null, "blurb": "Fatty fish (salmon, sardines, mackerel) once or twice a week.", "sources": [{"title": "Seafood Long-Chain n-3 Polyunsaturated Fatty Acids and Cardiovascular Disease: A Science Advisory From the American Heart Association", "authors": "Rimm EB, Appel LJ, Chiuve SE, et al.", "year": 2018, "journal": "Circulation", "doi": "10.1161/CIR.0000000000000574", "pmid": "29773586", "pmcid": "PMC6903778", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6903778/", "type": "guideline", "summary": "American Heart Association science advisory reviewing observational studies and trials on seafood omega-3 fats and cardiovascular disease. It concludes that 1-2 seafood meals per week lower the risk of heart failure, coronary heart disease, ischemic stroke and sudden cardiac death. The benefit is clearest when fish replaces less healthy foods, and the authors note longer dietary trials are still needed.", "highlight": "We conclude that 1 to 2 seafood meals per week be included to reduce the risk of congestive heart failure, coronary heart disease"}, {"title": "Fish intake, contaminants, and human health: evaluating the risks and the benefits", "authors": "Mozaffarian D, Rimm EB", "year": 2006, "journal": "JAMA", "doi": "10.1001/jama.296.15.1885", "pmid": "17047219", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/17047219/", "type": "review", "summary": "Systematic review and meta-analysis in JAMA weighing the cardiovascular benefits of fish against risks from mercury, dioxins and PCBs. Eating 1-2 servings a week, especially oily fish, was associated with 36% lower coronary death and 17% lower total mortality. Benefits outweigh contaminant risks for most adults, but very high eaters and women of childbearing age should limit high-mercury species.", "highlight": "reduces risk of coronary death by 36% (95% confidence interval, 20%-50%; P<.001) and total mortality by 17%"}, {"title": "Fish Consumption and the Risk of Chronic Disease: An Umbrella Review of Meta-Analyses of Prospective Cohort Studies", "authors": "Jayedi A, Shab-Bidar S", "year": 2020, "journal": "Advances in nutrition (Bethesda, Md.)", "doi": "10.1093/advances/nmaa029", "pmid": "32207773", "pmcid": "PMC7490170", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7490170/", "type": "meta-analysis", "summary": "Umbrella review of 34 meta-analyses covering 298 prospective cohort studies on fish intake and 40 chronic disease outcomes. Each extra 100 g/day of fish was linked to 8% lower all-cause mortality and 25% lower cardiovascular mortality, with lower risk of heart attack, stroke, heart failure and depression. The evidence is observational and rated moderate at best, and there was no clear link with most cancers.", "highlight": "evidence of moderate quality suggests that fish consumption is associated with a lower risk of cardiovascular disease, depression, and mortality"}]}, {"id": "redmeat", "label": "Red meat", "title": "Red meat", "tier": "weekly", "group": null, "blurb": "Unprocessed, once a week. The benefit lives in moderation.", "sources": [{"title": "Meat nutritional composition and nutritive role in the human diet", "authors": "Pereira PM, Vicente AF", "year": 2013, "journal": "Meat science", "doi": "10.1016/j.meatsci.2012.09.018", "pmid": "23273468", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23273468/", "type": "review", "summary": "Narrative review of the nutritional composition of meat and its role in the human diet. It describes meat as a rich source of high-quality protein, iron, vitamin B12 and other B vitamins, zinc, selenium and phosphorus. It is a composition review rather than an outcome study, and it explicitly advises moderation and separating fresh meat cuts from processed products.", "highlight": "Meat is a valuable source of high biological value protein, iron, vitamin B12 as well as other B complex vitamins, zinc, selenium and phosphorus"}, {"title": "Red and Processed Meat Consumption and Risk for All-Cause Mortality and Cardiometabolic Outcomes: A Systematic Review and Meta-analysis of Cohort Studies", "authors": "Zeraatkar D, Han MA, Guyatt GH, et al.", "year": 2019, "journal": "Annals of internal medicine", "doi": "10.7326/M19-0655", "pmid": "31569213", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31569213/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 55 cohorts with over 4 million participants on red and processed meat and mortality and cardiometabolic disease. Cutting unprocessed red meat by 3 servings a week was associated with a very small reduction in cardiovascular death, stroke, heart attack and type 2 diabetes, with similar small effects for processed meat. The evidence was low certainty, which supports eating unprocessed red meat in moderation but does not show high intake is harmless.", "highlight": "between red and processed meat consumption and all-cause mortality and adverse cardiometabolic outcomes is very small, and the evidence is of low certainty"}, {"title": "Meat consumption and risk of 25 common conditions: outcome-wide analyses in 475,000 men and women in the UK Biobank study", "authors": "Papier K, Fensom GK, Knuppel A, et al.", "year": 2021, "journal": "BMC medicine", "doi": "10.1186/s12916-021-01922-9", "pmid": "33648505", "pmcid": "PMC7923515", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7923515/", "type": "cohort", "summary": "UK Biobank cohort of about 475,000 adults followed for 8 years, testing meat intake against 25 common non-cancer conditions. Each extra 70 g/day of red and processed meat was linked to 15% higher heart disease risk and 30% higher diabetes risk, while unprocessed red meat was linked to 20% lower iron-deficiency anaemia per 50 g/day. Much of the excess risk shrank after adjusting for BMI, so the honest read is that a modest amount supplies iron while high intake carries risk.", "highlight": "Higher consumption of unprocessed red meat alone was associated with a lower risk of iron deficiency anaemia"}]}, {"id": "organ", "label": "Liver", "title": "Liver & organ meat", "tier": "weekly", "group": null, "blurb": "A small serving once a week; more than that risks too much vitamin A.", "sources": [{"title": "Priority Micronutrient Density in Foods", "authors": "Beal T, Ortenzi F", "year": 2022, "journal": "Frontiers in nutrition", "doi": "10.3389/fnut.2022.806566", "pmid": "35321287", "pmcid": "PMC8936507", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8936507/", "type": "review", "summary": "Analysis of an aggregated global food composition database ranking foods by density of six commonly lacking micronutrients: iron, zinc, folate, vitamin A, calcium and vitamin B12. Organ meats ranked as the top source of these priority micronutrients, ahead of small fish, leafy greens, shellfish and beef. This is a nutrient-density ranking, not a health outcome study, so it shows what organ meat supplies rather than proving it improves health.", "highlight": "the top sources of priority micronutrients are organs, small fish, dark green leafy vegetables, bivalves, crustaceans, goat, beef, eggs"}, {"title": "Characterization of Hanwoo Bovine By-products by Means of Yield, Physicochemical and Nutritional Compositions", "authors": "Seong PN, Kang GH, Park KM, et al.", "year": 2014, "journal": "Korean journal for food science of animal resources", "doi": "10.5851/kosfa.2014.34.4.434", "pmid": "26761281", "pmcid": "PMC4662147", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4662147/", "type": "review", "summary": "Laboratory analysis of yield and nutrient composition across edible by-products of Korean Hanwoo cattle, including liver, kidney, heart and spleen. Liver had the highest vitamin A, riboflavin, niacin and copper content of the organs tested, and most by-products were good sources of essential amino acids and minerals. It is a single-breed composition study with no health outcomes, so it supports liver as nutrient-dense but nothing more.", "highlight": "Liver had the highest vitamin A, B2 and niacin contents whereas the highest B1 and B5 contents were found in kidney"}, {"title": "The acute and chronic toxic effects of vitamin A", "authors": "Penniston KL, Tanumihardjo SA", "year": 2006, "journal": "The American journal of clinical nutrition", "doi": "10.1093/ajcn/83.2.191", "pmid": "16469975", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/16469975/", "type": "review", "summary": "Review in the American Journal of Clinical Nutrition of the acute and chronic toxic effects of preformed vitamin A from liver and supplements. It notes that preformed vitamin A intake often exceeds the RDA in developed countries and that intakes only about twice the RDA have been linked to osteoporosis and hip fracture. Liver is very high in preformed vitamin A, so a small weekly portion is sensible, and pregnant women and supplement users should be especially careful.", "highlight": "Osteoporosis and hip fracture are associated with preformed vitamin A intakes that are only twice the current RDA"}]}, {"id": "run10k", "label": "Long run 10K+", "title": "Long run, 10K+", "tier": "monthly", "group": null, "blurb": "Once a month, go long: 10 km or more.", "sources": [{"title": "Association of Cardiorespiratory Fitness With Long-term Mortality Among Adults Undergoing Exercise Treadmill Testing", "authors": "Mandsager K, Harb S, Cremer P, et al.", "year": 2018, "journal": "JAMA network open", "doi": "10.1001/jamanetworkopen.2018.3605", "pmid": "30646252", "pmcid": "PMC6324439", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6324439/", "type": "cohort", "summary": "Retrospective cohort of 122,007 patients who had treadmill exercise testing at the Cleveland Clinic, followed for a median 8.4 years. Elite fitness was associated with 80% lower mortality than low fitness, and being unfit carried as much or more risk than smoking, diabetes or coronary disease. The cohort was patients referred for testing, not the general public, but no upper limit of benefit was seen for fitness.", "highlight": "Cardiorespiratory fitness is inversely associated with long-term mortality with no observed upper limit of benefit"}, {"title": "Cardiorespiratory Fitness and Mortality Risk Across the Spectra of Age, Race, and Sex", "authors": "Kokkinos P, Faselis C, Samuel IBH, et al.", "year": 2022, "journal": "Journal of the American College of Cardiology", "doi": "10.1016/j.jacc.2022.05.031", "pmid": "35926933", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/35926933/", "type": "cohort", "summary": "Cohort of 750,302 US veterans aged 30-95 with treadmill-measured fitness, followed for a median 10.2 years. The least fit 20% had about 4-fold higher mortality than the most fit, and the lowest risk was around 14 METs with no increase at extremely high fitness. The population was mostly older men, but the graded benefit held across age, sex and race.", "highlight": "Being unfit carried a greater risk than any of the cardiac risk factors examined"}, {"title": "Cardiac arrest during long-distance running races", "authors": "Kim JH, Malhotra R, Chiampas G, et al.", "year": 2012, "journal": "The New England journal of medicine", "doi": "10.1056/NEJMoa1106468", "pmid": "22236223", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22236223/", "type": "cohort", "summary": "Registry study of cardiac arrests among 10.9 million runners in US marathons and half-marathons from 2000 to 2010. Cardiac arrest occurred in 0.54 per 100,000 participants, higher in marathons (1.01 per 100,000) than half-marathons and mostly in men, often from hypertrophic cardiomyopathy or coronary disease. The absolute risk of long-distance running is very low, but it is not zero, so training up gradually and checking heart risk factors is sensible.", "highlight": "Marathons and half-marathons are associated with a low overall risk of cardiac arrest and sudden death"}]}, {"id": "threshold", "label": "Threshold session", "title": "Threshold session", "tier": "monthly", "group": null, "blurb": "Once a month, one session at your limit: 20–30 minutes at lactate threshold (comfortably hard, about 8/10 effort), or a 20-minute time trial to re-test your threshold and track progress.", "sources": [{"title": "Effect of training on lactate/ventilatory thresholds: a meta-analysis", "authors": "Londeree BR", "year": 1997, "journal": "Medicine & Science in Sports & Exercise", "doi": "10.1097/00005768-199706000-00016", "pmid": "9219214", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/9219214/", "type": "meta-analysis", "summary": "This meta-analysis combined 85 study groups from 34 studies to see how training intensity affects oxygen uptake at the lactate or ventilatory threshold. Sedentary people improved their threshold strongly (effect size 2.32), while already-trained people gained less and tended to respond better to higher intensity (effect size 1.1 vs 0.4). It is old and small by modern standards, but it supports threshold work for beginners and suggests trained people need harder sessions too.", "highlight": "training at an intensity near the lactate or ventilatory threshold is an adequate training stimulus for improving the thresholds for sedentary subjects"}, {"title": "Polarized training has greater impact on key endurance variables than threshold, high intensity, or high volume training", "authors": "Stöggl T, Sperlich B", "year": 2014, "journal": "Frontiers in Physiology", "doi": "10.3389/fphys.2014.00033", "pmid": "24550842", "pmcid": "PMC3912323", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3912323/", "type": "RCT", "summary": "Forty-eight well-trained runners, cyclists, triathletes and skiers were randomized to nine weeks of polarized, threshold, high-intensity, or high-volume training. Polarized training produced the largest gains (VO2peak up 11.7%), while the threshold-focused group showed no further improvement in most performance measures. This argues against making threshold the bulk of your training, while still allowing it as an occasional session or test; groups were small (about 12 each) and short.", "highlight": "THR or HVT did not lead to further improvements in performance related variables."}, {"title": "Comparison of Polarized Versus Other Types of Endurance Training Intensity Distribution on Athletes' Endurance Performance: A Systematic Review with Meta-analysis", "authors": "Silva Oliveira P, Boppre G, Fonseca H", "year": 2024, "journal": "Sports Medicine", "doi": "10.1007/s40279-024-02034-z", "pmid": "38717713", "pmcid": "PMC11329428", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11329428/", "type": "meta-analysis", "summary": "This meta-analysis pooled 17 studies (437 athletes) comparing polarized training with other intensity distributions, including threshold-heavy plans, for at least four weeks. Polarized training gave a small edge in VO2peak (SMD 0.24), but time-trial results and speed or power at threshold improved about the same either way. In practice, how you spread intensity matters less than people claim, and a periodic threshold session or time trial is a reasonable way to track progress.", "highlight": "However, the effect of POL was similar to that of other TIDs on the remaining surrogates of endurance performance."}]}, {"id": "coldplunge", "label": "Cold plunge", "title": "Cold plunge", "tier": "monthly", "group": null, "blurb": "Cold-water immersion, around 10–15°C for 2–5 minutes. Not right after strength training: it can blunt muscle growth.", "sources": [{"title": "Health effects of voluntary exposure to cold water - a continuing subject of debate", "authors": "Esperland D, de Weerd L, Mercer JB", "year": 2022, "journal": "International journal of circumpolar health", "doi": "10.1080/22423982.2022.2111789", "pmid": "36137565", "pmcid": "PMC9518606", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9518606/", "type": "systematic review", "summary": "Literature review of 104 studies on the health effects of voluntary cold-water immersion and winter swimming in humans. Cold water appears to reduce or brown body fat and improve insulin sensitivity, and some studies report benefits for mood and immunity. Most studies were small, often single-sex, and used different temperatures and protocols, so the authors conclude benefits remain unproven and a subject of debate.", "highlight": "Some of the studies indicate that voluntary exposure to cold water has some beneficial health effects"}, {"title": "The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial", "authors": "Buijze GA, Sierevelt IN, van der Heijden BC, et al.", "year": 2016, "journal": "PloS one", "doi": "10.1371/journal.pone.0161749", "pmid": "27631616", "pmcid": "PMC5025014", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5025014/", "type": "RCT", "summary": "Randomized trial of 3,018 Dutch adults assigned to finish daily showers with 30, 60 or 90 seconds of cold water, or a usual-shower control, for 30 days then at their discretion for 60 more days. The cold-shower groups had 29% fewer sickness-absence days from work (IRR 0.71), but no reduction in the number of days actually ill. The trial was unblinded and outcomes were self-reported, so the effect may reflect perception or resilience more than immunity; duration of cold did not matter.", "highlight": "A routine (hot-to-) cold shower resulted in a statistical reduction of self-reported sickness absence but not illness days"}, {"title": "Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training", "authors": "Roberts LA, Raastad T, Markworth JF, et al.", "year": 2015, "journal": "The Journal of physiology", "doi": "10.1113/JP270570", "pmid": "26174323", "pmcid": "PMC4594298", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4594298/", "type": "RCT", "summary": "Two linked experiments: 21 active men strength trained for 12 weeks with either 10 minutes of cold-water immersion or active recovery after each session, plus a 9-man biopsy study of acute muscle signalling. The cold-water group gained less strength and muscle; type II fibre size rose 17% and myonuclei 26% with active recovery but not with cold immersion, and anabolic signalling was blunted. If building muscle is a goal, keep cold plunges away from lifting sessions (separate by several hours or do them on non-lifting days).", "highlight": "CWI attenuates the acute changes in satellite cell numbers and activity of kinases that regulate muscle hypertrophy"}]}, {"id": "fast24", "label": "24-hour fast", "title": "24-hour fast", "tier": "monthly", "group": null, "blurb": "Once a month: dinner to dinner, water, tea and black coffee only. Skip it if you are on insulin or glucose-lowering drugs without a doctor's plan.", "sources": [{"title": "Randomized controlled trial of once-per-week intermittent fasting for health improvement: the WONDERFUL trial", "authors": "Bartholomew CL, Muhlestein JB, May HT, et al.", "year": 2021, "journal": "European Heart Journal Open", "doi": "10.1093/ehjopen/oeab026", "pmid": "35919268", "pmcid": "PMC9241570", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9241570/", "type": "RCT", "summary": "Intermountain researchers randomized 103 adults with metabolic syndrome features and modestly high LDL to 24-hour water-only fasts (twice weekly for 4 weeks, then once weekly for 22 weeks) or normal eating. The fasting did not lower LDL (the primary outcome) but did improve insulin resistance (HOMA-IR -0.75 vs -0.10) and metabolic syndrome score. Dropout was high (only 71 of 103 finished) and the schedule was weekly, so a once-a-month 24-hour fast is a much smaller dose than what was tested.", "highlight": "A low-frequency intermittent fasting regimen did not reduce LDL-C or improve cognitive function but significantly reduced both HOMA-IR and MSS."}, {"title": "Relation of routine, periodic fasting to risk of diabetes mellitus, and coronary artery disease in patients undergoing coronary angiography", "authors": "Horne BD, Muhlestein JB, May HT, et al.", "year": 2012, "journal": "American Journal of Cardiology", "doi": "10.1016/j.amjcard.2012.01.379", "pmid": "22425331", "pmcid": null, "url": "https://doi.org/10.1016/j.amjcard.2012.01.379", "type": "cohort", "summary": "Intermountain surveyed 200 patients having coronary angiography about routine periodic fasting (largely the monthly Latter-day Saint fast) and pooled them with 448 patients from an earlier study. Routine fasters had less diabetes (10.3% vs 22.0%, OR 0.41) and less coronary artery disease (63.2% vs 75.0%, OR 0.42). This is observational and fasters in Utah differ in religion and lifestyle from non-fasters, so it shows association, not that monthly fasting causes the benefit.", "highlight": "prospective hypothesis testing showed that routine periodic fasting was associated with a lower prevalence of DM in patients undergoing coronary angiography"}, {"title": "Flipping the Metabolic Switch: Understanding and Applying the Health Benefits of Fasting", "authors": "Anton SD, Moehl K, Donahoo WT, et al.", "year": 2018, "journal": "Obesity (Silver Spring)", "doi": "10.1002/oby.22065", "pmid": "29086496", "pmcid": "PMC5783752", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5783752/", "type": "review", "summary": "This narrative review (Anton, Mattson and colleagues) describes what happens physiologically when a fast runs long enough to deplete liver glycogen and shift the body to burning fat and ketones. That 'metabolic switch' typically begins beyond about 12 hours without food, so a 24-hour fast clearly crosses it, and the authors argue it triggers stress-resistance and repair pathways. Much of the mechanistic support comes from animal studies, and the review itself calls for human trials that measure ketones to confirm dose and effect.", "highlight": "the point of negative energy balance at which liver glycogen stores are depleted and fatty acids are mobilized (typically beyond 12 hours after cessation of food intake)"}]}, {"id": "dentist", "label": "Dentist cleaning", "title": "Dentist cleaning", "tier": "annual", "group": null, "blurb": "A professional cleaning and checkup at least once a year (most dentists suggest every six months).", "sources": [{"title": "Routine scale and polish for periodontal health in adults", "authors": "Lamont T, Worthington HV, Clarkson JE, et al.", "year": 2018, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD004625.pub5", "pmid": "30590875", "pmcid": "PMC6516960", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6516960/", "type": "systematic review", "summary": "Cochrane review of two UK general-practice randomized trials (1,711 adults without severe periodontitis who were regular dental attenders) comparing 6- or 12-monthly scale and polish versus no scheduled cleanings over 2-3 years. Routine scaling and polishing made little or no difference to gingivitis, pocket depth or oral-health quality of life (high-certainty evidence), though it modestly reduced tartar. The value of a checkup for low-risk people lies more in early detection than the cleaning itself; people with gum disease or high risk likely benefit more.", "highlight": "routine scale and polish treatment makes little or no difference to gingivitis, probing depths and oral health-related quality of life"}, {"title": "Treatment of periodontitis for glycaemic control in people with diabetes mellitus", "authors": "Simpson TC, Clarkson JE, Worthington HV, et al.", "year": 2022, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD004714.pub4", "pmid": "35420698", "pmcid": "PMC9009294", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9009294/", "type": "systematic review", "summary": "Cochrane review of 35 randomized trials (3,249 people with diabetes and periodontitis) comparing professional periodontal treatment below the gumline with no treatment or usual care. Treatment lowered HbA1c by about 0.43 percentage points at 3-4 months and 0.30 at 6 months (moderate-certainty evidence), a clinically meaningful drop similar to adding a second diabetes drug. This applies to people who already have gum disease and diabetes, and most trials lasted 12 months or less.", "highlight": "periodontal treatment using subgingival instrumentation improves glycaemic control in people with both periodontitis and diabetes by a clinically significant amount"}, {"title": "Oral care measures for preventing nursing home-acquired pneumonia", "authors": "Cao Y, Liu C, Lin J, et al.", "year": 2022, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD012416.pub3", "pmid": "36383760", "pmcid": "PMC9668328", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9668328/", "type": "systematic review", "summary": "Cochrane review of six randomized trials (6,244 nursing home residents) comparing professional oral care with usual self-administered oral care for preventing pneumonia. Professional care did not clearly reduce pneumonia incidence, but two trials found it may cut pneumonia-related deaths by more than half at 24 months (RR 0.43). All trials were at high risk of bias and the evidence is low certainty, and it applies to frail older adults rather than healthy people.", "highlight": "professional oral care may reduce the risk of pneumonia-associated mortality compared with usual oral care at 24 months' follow-up"}]}, {"id": "parasite", "label": "Parasite cleanse", "title": "Parasite cleanse", "tier": "annual", "group": null, "blurb": "Once a year. The options: ivermectin (prescription), pyrantel pamoate (over the counter in the US), or papaya seeds with pumpkin seeds. The studies below were all done in people with confirmed infections, so a stool test first (ova & parasites) tells you whether there's anything to treat. Ask a doctor before taking ivermectin.", "sources": [{"title": "Ivermectin versus albendazole or thiabendazole for Strongyloides stercoralis infection.", "authors": "Henriquez-Camacho C, Gotuzzo E, Echevarria J, et al.", "year": 2016, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD007745.pub3", "pmid": "26778150", "pmcid": "PMC4916931", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4916931/", "type": "systematic review", "summary": "This Cochrane review pooled seven randomized trials (1147 participants) comparing ivermectin with albendazole or thiabendazole in people with confirmed chronic Strongyloides infection. Ivermectin cured more people than albendazole (risk ratio 1.79, moderate-quality evidence) and was at least as well tolerated, with no serious adverse events reported. It applies only to diagnosed infection, ivermectin is prescription-only in the US, and nothing here supports taking it as a routine yearly cleanse.", "highlight": "Ivermectin results in more people cured than albendazole, and is at least as well tolerated."}, {"title": "Efficacy of current drugs against soil-transmitted helminth infections: systematic review and meta-analysis.", "authors": "Keiser J, Utzinger J", "year": 2008, "journal": "JAMA", "doi": "10.1001/jama.299.16.1937", "pmid": "18430913", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/18430913/", "type": "meta-analysis", "summary": "This meta-analysis pooled 20 randomized trials of single-dose albendazole, mebendazole, levamisole and pyrantel pamoate against roundworm, hookworm and whipworm, mostly in children in highly endemic regions. Single-dose pyrantel pamoate, the main over-the-counter dewormer in the US, cured 88% of roundworm infections but only 31% of hookworm infections, and no pooled estimate was possible for whipworm. The pyrantel data are thin (131 and 152 patients), it does not cover many parasites, and the trials treated infected people rather than testing a yearly cleanse in healthy adults.", "highlight": "Single-dose oral albendazole, mebendazole, and pyrantel pamoate show high cure rates against A lumbricoides."}, {"title": "Effectiveness of dried Carica papaya seeds against human intestinal parasitosis: a pilot study.", "authors": "Okeniyi JA, Ogunlesi TA, Oyelami OA, Adeyemi LA", "year": 2007, "journal": "Journal of Medicinal Food", "doi": "10.1089/jmf.2005.065", "pmid": "17472487", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/17472487/", "type": "RCT", "summary": "This small randomized pilot trial gave 60 Nigerian children with parasites confirmed on stool microscopy a single 20 mL dose of either air-dried papaya seed and honey elixir or honey alone. Stools cleared of parasites in 77% of the papaya group versus 17% of the honey group at 7 days, with no harmful effects reported. It is one small, short trial in infected children in a high-prevalence setting with no comparison to standard drugs, so it does not show that papaya seeds work as a cleanse for people without an infection.", "highlight": "Significantly more subjects given CPH elixir than those given honey had their stools cleared of parasites"}, {"title": "Usefulness of pumpkin seeds combined with areca nut extract in community-based treatment of human taeniasis in northwest Sichuan Province, China.", "authors": "Li T, Ito A, Chen X, et al.", "year": 2012, "journal": "Acta Tropica", "doi": "10.1016/j.actatropica.2012.08.002", "pmid": "22910218", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22910218/", "type": "cohort", "summary": "This non-randomized community study in Sichuan, China, treated 115 suspected tapeworm cases with pumpkin seeds plus areca nut extract and compared small groups given either one alone. In the 45 confirmed cases, 89% expelled intact worms after the combination, usually within about 2 hours, while pumpkin seeds alone worked in 9 of 12 confirmed cases but took about 14 hours. The groups were small and not randomized, nearly half of patients had nausea or dizziness, and areca nut is a known carcinogen, so this is not support for eating pumpkin seeds as a routine cleanse.", "highlight": "The pumpkin seed/areca combined treatment was indicated to be safe and highly effective (89%) for human taeniasis."}]}, {"id": "bloodtest", "label": "Blood test", "title": "Annual blood test", "tier": "annual", "group": null, "blurb": "Once a year at minimum (Bryan Johnson draws blood every 3–6 months). The markers below are the ones in his Blueprint baseline panel.", "sources": [{"title": "General health checks in adults for reducing morbidity and mortality from disease", "authors": "Krogsbøll LT, Jørgensen KJ, Gøtzsche PC", "year": 2019, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD009009.pub3", "pmid": "30699470", "pmcid": "PMC6353639", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6353639/", "type": "systematic review", "summary": "Cochrane review of 17 randomised trials with about 252,000 adults comparing general health checks with no checks. Health checks had little or no effect on total mortality (RR 1.00), cancer mortality or cardiovascular mortality, based mostly on high-certainty evidence. This means broad untargeted checkups do not save lives on their own, so the value of a yearly blood test lies in specific, evidence-backed markers acted on when abnormal.", "highlight": "Health checks have little or no effect on total mortality (risk ratio (RR) 1.00, 95% confidence interval (CI) 0.97 to 1.03"}, {"title": "Screening for Prediabetes and Type 2 Diabetes: US Preventive Services Task Force Recommendation Statement", "authors": "US Preventive Services Task Force, Davidson KW, Barry MJ, et al.", "year": 2021, "journal": "JAMA", "doi": "10.1001/jama.2021.12531", "pmid": "34427594", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/34427594/", "type": "guideline", "summary": "USPSTF recommendation statement based on a commissioned systematic review of screening for prediabetes and type 2 diabetes in asymptomatic adults. It concludes with moderate certainty that screening adults aged 35-70 with overweight or obesity, and referring those with prediabetes to prevention programs, has a moderate net benefit (B grade). The recommendation is targeted to a risk group rather than everyone, which is how screening tends to earn its benefit.", "highlight": "The USPSTF recommends screening for prediabetes and type 2 diabetes in adults aged 35 to 70 years who have overweight or obesity"}, {"title": "Apolipoprotein B Particles and Cardiovascular Disease: A Narrative Review", "authors": "Sniderman AD, Thanassoulis G, Glavinovic T, et al.", "year": 2019, "journal": "JAMA cardiology", "doi": "10.1001/jamacardio.2019.3780", "pmid": "31642874", "pmcid": "PMC7369156", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7369156/", "type": "review", "summary": "Narrative review in JAMA Cardiology of the biology and evidence behind apolipoprotein B as a measure of atherogenic lipoprotein particles. It argues apoB counts the particles that actually drive plaque and captures cardiovascular risk more accurately than LDL cholesterol or non-HDL cholesterol. It is a narrative review by advocates rather than a trial, but it makes a solid case for adding apoB to a routine lipid panel.", "highlight": "Apolipoprotein B unifies, amplifies, and simplifies the information from the conventional lipid markers as to the atherogenic risk attributable to the apoB lipoproteins"}], "markers": [["Heart & lipids", "ApoB, Lp(a), LDL-C, LDL particle number & size, HDL-C, triglycerides, total & non-HDL cholesterol"], ["Blood sugar & metabolism", "fasting glucose, HbA1c, fasting insulin, leptin, uric acid"], ["Inflammation & immune", "hs-CRP, homocysteine, white blood cell count with differential, ANA, rheumatoid factor"], ["Complete blood count", "red blood cells, hemoglobin, hematocrit, MCV, MCH, RDW, platelets"], ["Liver, kidney & pancreas", "ALT, AST, GGT, alkaline phosphatase, bilirubin, albumin, total protein, creatinine, eGFR, BUN, amylase, lipase, urinalysis"], ["Electrolytes & minerals", "sodium, potassium, chloride, CO2, calcium, magnesium, zinc"], ["Vitamins & nutrients", "vitamin D, methylmalonic acid (for B12 status), ferritin, iron, iron-binding capacity, iron saturation, omega-3 index (EPA, DPA, DHA), omega-6/omega-3 ratio"], ["Hormones & thyroid", "TSH, free T4, free T3, TPO and thyroglobulin antibodies, total & free testosterone, estradiol, SHBG, DHEA-S, cortisol, LH, FSH, prolactin"], ["Toxins", "lead, mercury"], ["Sex-specific", "PSA (men), AMH (women)"], ["Brain", "pTau217, an early Alzheimer's risk marker, on Bryan's protocol"]], "markers_src": [["Blueprint baseline biomarker panel", "https://immortals.com/pages/biomarkers"], ["Bryan Johnson's protocol", "https://protocol.bryanjohnson.com/"]]}, {"id": "fast3to5", "label": "3–5 day fast", "title": "3–5 day fast", "tier": "annual", "group": null, "blurb": "Once a year, water-only or a fasting-mimicking diet. Do it with medical supervision: electrolytes matter, and breaking it (refeeding) needs care.", "sources": [{"title": "Fasting-mimicking diet and markers/risk factors for aging, diabetes, cancer, and cardiovascular disease", "authors": "Wei M, Brandhorst S, Shelehchi M, et al.", "year": 2017, "journal": "Science Translational Medicine", "doi": "10.1126/scitranslmed.aai8700", "pmid": "28202779", "pmcid": "PMC6816332", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6816332/", "type": "RCT", "summary": "100 generally healthy US adults were randomized to normal eating or a 5-day low-calorie, low-protein fasting-mimicking diet (FMD) once a month for 3 months, with controls later crossed over. Three FMD cycles reduced body weight, trunk fat, blood pressure and IGF-1, with no serious adverse effects, and benefits were larger in people already at risk. It was short, unblinded, had notable dropout, and was run by the diet's inventor (Longo, who holds equity in the company selling it), so the results need independent confirmation.", "highlight": "Three FMD cycles reduced body weight, trunk, and total body fat; lowered blood pressure; and decreased insulin-like growth factor 1 (IGF-1)."}, {"title": "Fasting-mimicking diet causes hepatic and blood markers changes indicating reduced biological age and disease risk", "authors": "Brandhorst S, Levine ME, Wei M, et al.", "year": 2024, "journal": "Nature Communications", "doi": "10.1038/s41467-024-45260-9", "pmid": "38378685", "pmcid": "PMC10879164", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10879164/", "type": "RCT", "summary": "This is a secondary, exploratory analysis of blood samples and liver MRI from FMD trial participants, replicated in a second clinical study. Three monthly 5-day FMD cycles were linked to lower insulin resistance, less liver fat, a younger immune profile, and a 2.5-year drop in median biological age independent of weight loss. Biological-age scores are surrogate markers, not lived years, and the work comes from the same group with a commercial stake in the product.", "highlight": "3 FMD cycles were associated with a decrease of 2.5 years in median biological age, independent of weight loss"}, {"title": "Safety, health improvement and well-being during a 4 to 21-day fasting period in an observational study including 1422 subjects", "authors": "Wilhelmi de Toledo F, Grundler F, Bergouignan A, et al.", "year": 2019, "journal": "PLoS One", "doi": "10.1371/journal.pone.0209353", "pmid": "30601864", "pmcid": "PMC6314618", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6314618/", "type": "cohort", "summary": "This one-year observational study followed 1,422 people doing Buchinger fasts of 4 to 21 days (about 200-250 kcal/day of juice and broth) under daily medical supervision in a German clinic. Weight, waist and blood pressure fell, ketones rose, 93.2% reported no hunger, and adverse effects occurred in under 1%. There was no control group, the clinic ran the study, and participants were screened and supervised; people on insulin or blood-pressure drugs, those with eating disorders, and anyone fasting at home without guidance on medications and gradual refeeding should not assume the same safety record.", "highlight": "Adverse effects were reported in less than 1% of the participants."}]}];
